WITH seed_questions(category_code, professional_field_code, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, cognitive_level) AS (
  VALUES
    ('BAI_1', 'CC-12', 'Đặc điểm cốt lõi phân biệt bệnh cấp tính với bệnh mạn tính là gì?', 'Diễn biến kéo dài và cần điều trị liên tục.', 'Khởi phát đột ngột, diễn biến nhanh và thời gian là yếu tố quyết định.', 'Luôn dẫn đến tử vong nếu không được can thiệp y tế.', 'Chỉ xảy ra ở những người có bệnh nền sẵn có.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Theo phân loại của Creed (2010), "Chăm sóc cấp cứu ban đầu" tập trung trọng tâm vào vấn đề nào?', 'Theo dõi sát để phát hiện sớm các dấu hiệu chuyển biến xấu.', 'Quản lý các tình trạng bệnh lý đã ổn định hơn.', 'Xử trí nhanh các tình trạng đe dọa tính mạng (ABC).', 'Hỗ trợ sự sống chuyên sâu như thở máy và thuốc vận mạch.', 'C', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Vai trò nào của điều dưỡng được coi là "tuyến đầu" trong việc phát hiện sớm các biến chứng của người bệnh?', 'Người giáo dục sức khỏe.', 'Người hỗ trợ tinh thần.', 'Người phối hợp đa ngành.', 'Người chăm sóc trực tiếp.', 'D', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Trong hệ thống tiếp cận ABCDE, chữ "D" (Disability) tập trung đánh giá yếu tố nào của người bệnh?', 'Tình trạng phơi nhiễm và môi trường.', 'Đánh giá tri giác và khiếm khuyết thần kinh.', 'Khả năng vận động của các chi.', 'Tình trạng bài tiết và tiêu hóa.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Đâu là ý nghĩa quan trọng nhất của vai trò "Người phối hợp đa ngành" trong chăm sóc cấp tính?', 'Giúp điều dưỡng thực hiện thủ thuật nhanh hơn.', 'Giảm bớt khối lượng công việc cho bác sĩ điều trị.', 'Đảm bảo sự liên tục, nhất quán và giảm nguy cơ sai sót y khoa.', 'Tăng cường sự hài lòng của gia đình người bệnh.', 'C', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Khi thực hiện nguyên tắc "6 đúng" trong an toàn dùng thuốc, bước "ghi chép đúng" có ý nghĩa gì?', 'Để thanh toán viện phí chính xác.', 'Để báo cáo với quản lý khi có sai sót.', 'Duy trì tính liên tục, minh bạch và là bằng chứng pháp lý.', 'Giúp người bệnh biết mình đã uống thuốc gì.', 'C', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Trong chăm sóc cấp tính, việc ưu tiên nhu cầu ABC (Airway - Breathing - Circulation) nhằm mục đích gì?', 'Hoàn thành quy trình kỹ thuật đúng thời gian.', 'Đảm bảo sự sống còn của người bệnh trong giai đoạn khẩn cấp.', 'Giảm lo âu cho gia đình người bệnh.', 'Phân loại bệnh nhân để chuyển khoa nhanh chóng.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Bước "Nhận định" trong quy trình điều dưỡng bệnh cấp tính yêu cầu thu thập loại dữ liệu nào?', 'Chỉ các chỉ số sinh tồn khách quan từ máy móc.', 'Các chẩn đoán bệnh lý của bác sĩ.', 'Cả dữ liệu khách quan và chủ quan thông qua phỏng vấn, quan sát, thăm khám.', 'Các xét nghiệm cận lâm sàng đã có kết quả.', 'C', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Điểm khác biệt lớn nhất về thủ tục giữa nhập viện thường và nhập viện cấp cứu là gì?', 'Nhập viện thường không cần khám lâm sàng ban đầu.', 'Nhập viện cấp cứu ưu tiên cứu sống trước, hoàn thiện giấy tờ sau.', 'Nhập viện thường ưu tiên xử trí ABCDE ngay tại cổng tiếp đón.', 'Nhập viện cấp cứu yêu cầu thẻ bảo hiểm y tế ngay khi tiếp nhận.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Vai trò "Người giáo dục" của điều dưỡng trong tình huống nhập viện cấp cứu khác gì so với nhập viện thường?', 'Tập trung hướng dẫn chế độ ăn uống và vận động lâu dài.', 'Giải thích chi tiết về cơ chế bệnh sinh của tình trạng cấp tính.', 'Giải thích nhanh về thủ thuật, quy trình và hướng dẫn gia đình hỗ trợ khẩn cấp.', 'Tư vấn cách phòng ngừa các bệnh mạn tính sau khi ra viện.', 'C', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Một bệnh nhân viêm phổi nặng có SpO2 giảm, điều dưỡng cần ưu tiên can thiệp nào đầu tiên theo nguyên tắc chăm sóc?', 'Đặt đường truyền tĩnh mạch để dùng kháng sinh.', 'Vệ sinh thân thể và thay đồ cho người bệnh.', 'Hỗ trợ thở oxy để đảm bảo hô hấp.', 'Lấy mẫu máu xét nghiệm theo chỉ định của bác sĩ.', 'C', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_1', 'CC-12', 'Theo chính sách nhân lực trong chăm sóc cấp tính, yếu tố nào thường được quy định chặt chẽ để giảm kiệt sức nghề nghiệp?', 'Tỷ lệ điều dưỡng trên số lượng bác sĩ của khoa.', 'Tỷ lệ điều dưỡng trên số lượng bệnh nhân (đặc biệt tại ICU/Cấp cứu).', 'Số lượng máy móc hỗ trợ trong một ca trực.', 'Thời gian nghỉ phép năm của nhân viên y tế.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Trong quy trình điều dưỡng, bước nào đóng vai trò xác định mục tiêu và kết quả mong đợi cho người bệnh?', 'Nhận định (Assessment).', 'Chẩn đoán (Diagnosis).', 'Lập kế hoạch (Planning).', 'Thực hiện (Implementation).', 'C', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', '"Chăm sóc tiến triển" (Progressive Care) được định nghĩa là gì?', 'Giai đoạn bệnh nhân mới nhập viện cấp cứu.', 'Cầu nối giữa ICU và khoa thường cho bệnh nhân đã qua giai đoạn nguy kịch.', 'Chăm sóc tại cộng đồng sau khi ra viện.', 'Chăm sóc tích cực cho bệnh nhân cần máy thở liên tục.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Nguyên tắc "Tôn trọng nhân phẩm và quyền của người bệnh" được thể hiện cụ thể qua hành động nào sau đây?', 'Thực hiện thủ thuật nhanh chóng để tiết kiệm thời gian cho bệnh nhân.', 'Giải thích trước khi làm thủ thuật và giữ kín thông tin cá nhân.', 'Quyết định thay cho bệnh nhân các phương án điều trị tốt nhất.', 'Chỉ cho phép người nhà vào thăm khi bệnh nhân yêu cầu.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Tại sao ghi chép điều dưỡng được coi là công cụ giao tiếp quan trọng trong nhóm chăm sóc?', 'Để bệnh nhân có thể đọc và hiểu về tình trạng của mình.', 'Để bác sĩ không cần phải khám lại bệnh nhân.', 'Giúp duy trì tính liên tục của thông tin giữa các ca trực và các bộ phận.', 'Để tính toán chi phí thuốc men hàng ngày.', 'C', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Đặc điểm "Thời gian là yếu tố quyết định" trong bệnh cấp tính có nghĩa là:', 'Bệnh nhân sẽ tự hồi phục sau một khoảng thời gian nhất định.', 'Mọi can thiệp chậm trễ đều dẫn đến di chứng mạn tính.', 'Việc đánh giá và can thiệp ngay lập tức ảnh hưởng trực tiếp đến kết quả điều trị.', 'Điều dưỡng cần ghi lại chính xác thời gian bệnh nhân nhập viện.', 'C', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Trong bước "Thực hiện" (Implementation) của quy trình điều dưỡng, hoạt động chính là gì?', 'Phân tích dữ liệu để tìm ra nguy cơ sức khỏe.', 'Tiến hành các can thiệp điều dưỡng đã đề ra trong kế hoạch.', 'Đánh giá mức độ đạt được mục tiêu sau điều trị.', 'Thu thập thêm các thông tin chủ quan từ người nhà.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Khi tiếp nhận bệnh nhân nhập viện thường, vai trò chính của điều dưỡng là gì?', 'Hồi sức tim phổi ngay lập tức.', 'Hỗ trợ hành chính, chăm sóc cơ bản và hướng dẫn nội quy khoa phòng.', 'Thực hiện các thủ thuật xâm lấn nhanh chóng.', 'Đánh giá nhanh tình trạng theo bảng phân loại cấp cứu.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Một bệnh nhân sau mổ ruột thừa lo lắng về việc học tập bị gián đoạn, điều dưỡng thực hiện can thiệp tâm lý thuộc nguyên tắc nào?', 'Ưu tiên nhu cầu cấp thiết.', 'Đánh giá toàn diện (thể chất, tâm lý, xã hội).', 'Đảm bảo an toàn cho người bệnh.', 'Ghi chép và báo cáo kịp thời.', 'B', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_1', 'CC-12', 'Theo chuẩn AACN, điều dưỡng chăm sóc cấp tính phải tuân thủ chính sách đạo đức nào?', 'Luôn thực hiện theo yêu cầu của gia đình bệnh nhân.', 'Duy trì tính chuyên nghiệp và tôn trọng nhân phẩm người bệnh.', 'Không được phép báo cáo các sai sót y khoa của đồng nghiệp.', 'Ưu tiên điều trị cho những bệnh nhân có bảo hiểm chi trả cao.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Trong nhập viện cấp cứu, trình tự tiếp đón đúng là:', 'Hành chính -> Khám -> Xử trí.', 'Đánh giá nhanh -> Xử trí cấp cứu -> Ghi nhận song song -> Chuyển khoa.', 'Khám -> Hướng dẫn -> Hành chính -> Chăm sóc.', 'Ghi nhận thông tin -> Đóng viện phí -> Xử trí cấp cứu.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Ví dụ nào sau đây thể hiện vai trò "Người hỗ trợ tinh thần" của điều dưỡng?', 'Hướng dẫn bệnh nhân cách thay băng vết thương.', 'Trấn an bệnh nhân trẻ tuổi trước khi bước vào phẫu thuật cấp cứu.', 'Báo cáo bác sĩ khi thấy huyết áp bệnh nhân tăng cao.', 'Kiểm tra 6 đúng trước khi cho bệnh nhân uống thuốc.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Chăm sóc tích cực (Critical Care/ICU) dành cho đối tượng bệnh nhân nào?', 'Bệnh nhân đã ổn định tình trạng và chuẩn bị ra viện.', 'Bệnh nhân nặng, cần các phương tiện hỗ trợ sự sống và theo dõi liên tục.', 'Bệnh nhân có tình trạng cấp tính nhưng chưa đe dọa tính mạng.', 'Bệnh nhân nhập viện để thực hiện các xét nghiệm tầm soát.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Tại sao quy trình điều dưỡng được mô tả là một vòng chu kỳ và liên tục?', 'Vì bệnh nhân phải nhập viện nhiều lần.', 'Vì kết quả đánh giá sẽ là cơ sở để điều chỉnh lại kế hoạch chăm sóc nếu cần.', 'Vì điều dưỡng phải lặp lại các thủ thuật mỗi ngày.', 'Vì nó giúp tiết kiệm thời gian ghi chép hồ sơ.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Trong chính sách đảm bảo chất lượng, việc tuân thủ "Thực hành dựa trên bằng chứng" (Evidence-Based Practice) có ý nghĩa:', 'Sử dụng các phương pháp chăm sóc theo thói quen kinh nghiệm.', 'Áp dụng các nghiên cứu khoa học và chuẩn chuyên môn vào chăm sóc người bệnh.', 'Chỉ thực hiện những gì bác sĩ yêu cầu bằng văn bản.', 'Ưu tiên sử dụng các thiết bị công nghệ đắt tiền nhất.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Mục tiêu chính của việc giải thích quy trình điều trị cho người bệnh (vai trò giáo dục) là:', 'Giảm bớt trách nhiệm giải trình của điều dưỡng.', 'Tăng sự tuân thủ và giúp người bệnh hợp tác trong quá trình điều trị.', 'Để người bệnh tự thực hiện các thủ thuật y tế.', 'Để bệnh nhân không hỏi thêm thông tin trong khi làm việc.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Hành động nào của điều dưỡng ICU thể hiện sự "Phối hợp đa ngành"?', 'Tự mình điều chỉnh liều thuốc vận mạch theo phán đoán cá nhân.', 'Trao đổi với bác sĩ gây mê và kỹ thuật viên xét nghiệm để điều chỉnh thuốc.', 'Chỉ làm việc độc lập để tránh gây nhầm lẫn thông tin.', 'Để gia đình tự quyết định các xét nghiệm cần thiết cho bệnh nhân.', 'B', NULL, 'FOUNDATION'),
    ('BAI_1', 'CC-12', 'Điều dưỡng nhận thấy SpO2 của bệnh nhân viêm phổi giảm và báo bác sĩ ngay, hành động này thuộc bước nào của quy trình điều dưỡng?', 'Lập kế hoạch.', 'Nhận định (và xử trí báo cáo kịp thời).', 'Chẩn đoán.', 'Đánh giá (sau khi đã can thiệp).', 'B', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_1', 'CC-12', 'Sự giống nhau căn bản trong vai trò của điều dưỡng giữa nhập viện thường và cấp cứu là gì?', 'Đều tập trung vào quản lý các bệnh mạn tính lâu dài.', 'Đều là trung tâm trong chăm sóc, phối hợp, giáo dục và hỗ trợ tinh thần.', 'Đều thực hiện các thủ tục hành chính khắt khe trước khi khám.', 'Đều chỉ chú trọng vào việc cứu sống người bệnh.', 'B', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Theo định nghĩa Berlin (2014), một bệnh nhân được phân loại là "Đa chấn thương" (Polytrauma) khi nào?', 'Có từ 2 chấn thương nặng trở lên và điểm ISS ≥ 16.', 'Có từ 2 chấn thương nặng kèm ít nhất 1 rối loạn sinh lý.', 'Có nhiều tổn thương do tác động cơ học và nguy cơ tử vong cao.', 'Có tổn thương ở ít nhất 2 vùng cơ thể khác nhau.', 'B', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Chỉ số sinh lý nào sau đây không thuộc tiêu chuẩn định nghĩa đa chấn thương của Berlin 2014?', 'Lactate > 2 mmol/L.', 'Điểm Glasgow (GCS) < 9.', 'Huyết áp tâm trương < 60 mmHg.', 'Tình trạng đông máu với INR > 1.4.', 'C', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Theo nguồn tài liệu, quan điểm hiện nay của ATLS và WHO về "Thời gian vàng" trong cấp cứu chấn thương là gì?', 'Là con số tuyệt đối 60 phút để cứu sống bệnh nhân.', 'Là giới hạn thời gian cố định cho mọi loại chấn thương.', 'Mang tính khái niệm, nhấn mạnh việc nhận diện và can thiệp càng sớm càng tốt.', 'Chỉ áp dụng cho các chấn thương nội tạng nghiêm trọng.', 'C', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Trong phân loại ưu tiên (Triage), bệnh nhân được xếp vào nhóm "Nguy kịch" (Critical) khi có đặc điểm:', 'Có rối loạn đe dọa tính mạng và cần đặt trong tầm mắt theo dõi.', 'Có tổn thương có thể tiến triển nặng nếu không điều trị nhanh.', 'Nguy cơ tử vong nhanh chóng nếu không can thiệp cấp cứu ngay lập tức.', 'Cần huy động toàn bộ trauma team nhưng có thể chờ sau 15 phút.', 'C', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Mục tiêu cốt lõi của việc đánh giá cấp I (Primary Survey) theo trình tự ABCDE là gì?', 'Phát hiện tất cả các tổn thương từ đầu đến chân.', 'Tìm và xử trí ngay các rối loạn đe dọa trực tiếp đến chức năng sống.', 'Khai thác tiền sử AMPLE để hỗ trợ chẩn đoán.', 'Thực hiện các xét nghiệm cận lâm sàng chuyên sâu để phân loại bệnh.', 'B', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Khi đánh giá đường thở [A], một câu trả lời phù hợp của người bệnh khi được hỏi tên phản ánh điều gì?', 'Đường thở thông thoáng, hô hấp tốt và ý thức không giảm sút nghiêm trọng.', 'Bệnh nhân hoàn toàn tỉnh táo và không có tổn thương cột sống cổ.', 'Áp lực nội sọ trong giới hạn bình thường.', 'Phổi đang được thông khí hiệu quả 100%.', 'A', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Việc đeo nẹp cổ (cervical collar) quá chặt ở bệnh nhân chấn thương có thể dẫn đến nguy cơ nào?', 'Gây liệt tủy thứ phát do chèn ép trực tiếp.', 'Làm tăng áp lực nội sọ do cản trở tĩnh mạch hồi lưu.', 'Khiến bệnh nhân bị tắc nghẽn đường thở cơ học.', 'Làm mất các mốc giải phẫu khi cần đặt nội khí quản.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_2', 'CC-12', 'Trong chấn thương hàm mặt nặng, tại sao việc thông khí bằng mặt nạ thường không khả thi?', 'Do mất cấu trúc xương làm mặt nạ không khít.', 'Do tình trạng co thắt thanh quản dữ dội.', 'Do máu trong khoang miệng gây cản trở và nguy cơ hít sặc.', 'Do bệnh nhân luôn trong tình trạng kích động mạnh.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_2', 'CC-12', 'Thủ thuật mở nhẫn giáp bằng kim được coi là giải pháp tạm thời giúp bổ sung oxy trong bao lâu?', '5 – 10 phút.', '30 – 45 phút.', '60 – 90 phút.', 'Cho đến khi bệnh nhân vào phòng mổ.', 'B', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Dấu hiệu nào được ưu tiên nhận định ngay để loại trừ tràn khí màng phổi áp lực trong bước [B]?', 'Tiếng thở rít và co kéo cơ hô hấp phụ.', 'Sự dịch chuyển của khí quản và tĩnh mạch cổ nổi.', 'Độ bão hòa Oxy (SpO2) giảm dưới 80%.', 'Hiện tượng hô hấp đảo chiều.', 'B', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Một bệnh nhân hít vào thấy bụng phồng lên nhưng ngực lại lõm vào. Đây là biểu hiện của tình trạng nào?', 'Liệt hoàn toàn cả cơ hoành và cơ liên sườn (tổn thương trên C3).', 'Liệt cơ hoành nhưng cơ liên sườn còn hoạt động.', 'Liệt tủy thấp (C5-T1) khiến cơ liên sườn liệt nhưng cơ hoành còn hoạt động.', 'Tràn khí màng phổi áp lực gây đè bẹp cơ hoành.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_2', 'CC-12', 'Theo bảng phân loại mức độ suy hô hấp cấp, bệnh nhân được coi là "Nguy kịch" khi nhịp thở đạt ngưỡng nào?', '25 - 30 lần/phút.', '30 - 40 lần/phút.', '> 40 hoặc < 10 lần/phút.', 'Luôn > 50 lần/phút.', 'C', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Trong sốc mất máu, huyết áp thường chỉ bắt đầu giảm khi lượng máu mất vượt quá bao nhiêu phần trăm?', '15% thể tích máu.', '20% thể tích máu.', '30% thể tích máu.', '40% thể tích máu.', 'C', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Tại sao kiểm soát đau lại được coi là một phần của hồi sức tuần hoàn [C] trong chấn thương?', 'Để bệnh nhân hợp tác hơn khi thực hiện thủ thuật.', 'Để ngăn chặn vòng xoắn bệnh lý dẫn đến "tam chứng tử vong".', 'Vì đau làm giảm nhịp tim và gây tụt huyết áp đột ngột.', 'Để tránh tình trạng liệt ruột sau chấn thương.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_2', 'CC-12', 'Kỹ thuật Log-roll (Lăn thành khối đồng bộ) được thực hiện chủ yếu ở bước nào của quy trình ABCDE?', 'Bước [B] để kiểm tra sự di động lồng ngực phía sau.', 'Bước [C] để kiểm tra các vết thương đang chảy máu ở lưng.', 'Bước [D] để đánh giá cột sống và các tổn thương phía sau.', 'Bước [E] để cởi bỏ hoàn toàn quần áo bệnh nhân.', 'C', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', '"Tam chứng tử vong" (Lethal Triad) trong chấn thương bao gồm các yếu tố nào?', 'Hạ huyết áp, mạch chậm, hôn mê.', 'Hạ thân nhiệt, toan máu, rối loạn đông máu.', 'Thiếu oxy não, tăng áp lực nội sọ, tụt kẹt não.', 'Vô niệu, tăng kali máu, ngừng tim.', 'B', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Đánh giá cấp 2 (Secondary Survey) chỉ được bắt đầu khi nào?', 'Ngay sau khi bệnh nhân nhập viện.', 'Sau khi đã tạm ổn định các chức năng sống (xong cấp 1).', 'Sau 24 giờ kể từ khi bị chấn thương.', 'Khi đã có kết quả chụp CT toàn thân.', 'B', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Nội dung nào sau đây không nằm trong trình tự khai thác bệnh sử AMPLE?', 'Tiền sử dị ứng (Allergies).', 'Các thuốc đang sử dụng (Medications).', 'Cơ chế chấn thương (Mechanism).', 'Thời gian bữa ăn cuối cùng (Last meal).', 'C', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', '"Tam chứng Cushing" (HA tăng, mạch chậm) là dấu hiệu báo động của tình trạng nào?', 'Sốc thần kinh do chấn thương cột sống cổ.', 'Chèn ép tim cấp.', 'Tăng áp lực nội sọ và đe dọa thoát vị não.', 'Vỡ eo động mạch chủ.', 'C', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Dấu hiệu đặc trưng để nhận biết rò dịch não tủy qua mũi/tai (vỡ nền sọ) là:', 'Dấu hiệu kính râm (Raccoon eyes).', 'Dấu hiệu vòng hào quang (Halo sign) trên gạc.', 'Dấu hiệu Battle (bầm tím xương chũm).', 'Chảy máu mũi không cầm được.', 'B', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Sốc thần kinh (tổn thương tủy trên T6) có đặc điểm lâm sàng khác biệt với sốc mất máu là:', 'Tụt huyết áp kèm mạch nhanh, da lạnh ẩm.', 'Tụt huyết áp kèm mạch chậm, da ấm và khô.', 'Huyết áp tăng cao kèm mạch chậm, da nhợt.', 'Mất phản xạ cơ thắt nhưng huyết áp vẫn ổn định.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_2', 'CC-12', 'Cơ chế sinh lý bệnh chính của Tràn khí màng phổi áp lực là gì?', 'Máu tích tụ trong khoang màng phổi đè bẹp nhu mô phổi.', 'Lỗ thủng lớn trên thành ngực khiến khí ra vào tự do.', 'Cơ chế van một chiều làm khí tích tụ gây áp lực dương đè bẹp tĩnh mạch chủ.', 'Phổi bị rách khiến khí thoát ra làm mất áp lực âm khoang màng phổi.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_2', 'CC-12', '"Tam chứng Beck" dùng để nhận diện tình trạng chèn ép tim cấp gồm những dấu hiệu nào?', 'Tĩnh mạch cổ nổi, huyết áp tụt, tiếng tim mờ xa.', 'Tĩnh mạch cổ nổi, huyết áp kẹt, lệch khí quản.', 'Mạch nghịch thường, đau ngực dữ dội, khó thở.', 'Huyết áp tay phải > tay trái, mất mạch bẹn, đau sau lưng.', 'A', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Một bệnh nhân gãy xương đùi, sau 24 giờ xuất hiện lú lẫn, suy hô hấp và các nốt xuất huyết vùng nách. Nghi ngờ gì?', 'Sốc nhiễm khuẩn diễn tiến sớm.', 'Hội chứng chèn ép khoang.', 'Tắc mạch do mỡ.', 'Tiêu cơ vân cấp.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_2', 'CC-12', 'Dấu hiệu sớm nhất và nhạy nhất của hội chứng chèn ép khoang là:', 'Mất mạch ngoại vi.', 'Liệt chi hoàn toàn.', 'Đau quá mức khi căng cơ thụ động và tê bì (dị cảm).', 'Chi bị chấn thương tím tái và lạnh.', 'C', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Trong chăm sóc người bệnh tiêu cơ vân (hội chứng vùi lấp), biến chứng nguy hiểm nhất gây ngừng tim là:', 'Suy thận cấp do Myoglobin.', 'Tăng Kali máu ồ ạt từ tế bào bị phá hủy.', 'Toan chuyển hóa nặng.', 'Hạ thân nhiệt kéo dài.', 'B', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Chẩn đoán điều dưỡng NANDA "Giảm tưới máu mô ngoại vi" cần can thiệp NIC ưu tiên nào?', 'Thiết lập 2 đường truyền lớn, bù dịch/máu nhanh.', 'Cho bệnh nhân nằm đầu cao 30 độ.', 'Đắp chăn ấm và truyền dịch ấm 37 độ C.', 'Kiểm tra 5P và mạch ngoại vi mỗi giờ.', 'A', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_2', 'CC-12', 'Tuyệt đối không được thực hiện thủ thuật nào khi nghi ngờ bệnh nhân bị vỡ nền sọ?', 'Đặt nội khí quản đường miệng.', 'Đặt sonde tiểu.', 'Đặt sonde dạ dày đường mũi.', 'Cố định cột sống cổ bằng nẹp cứng.', 'C', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Mục tiêu của việc duy trì huyết áp tâm thu > 90 mmHg và nước tiểu > 0.5 ml/kg/h trong sốc mất máu là:', 'Để đảm bảo bệnh nhân không bị suy thận.', 'Để duy trì tưới máu các cơ quan đích.', 'Để tránh tình trạng rối loạn đông máu.', 'Để chuẩn bị cho cuộc phẫu thuật sắp tới.', 'B', NULL, 'FOUNDATION'),
    ('BAI_2', 'CC-12', 'Đánh giá cấp 3 (Tertiary Survey) có vai trò gì trong quy trình chăm sóc chấn thương?', 'Là bước khám cuối cùng trước khi bệnh nhân xuất viện.', 'Thực hiện sau 24 giờ bởi đa chuyên khoa để tránh bỏ sót tổn thương.', 'Dùng để đánh giá hiệu quả của các can thiệp phẫu thuật.', 'Là bước phân loại lại bệnh nhân để chuyển tuyến.', 'B', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Theo hướng dẫn của WHS (Wound Healing Society), vết thương được phân loại chính dựa trên yếu tố nào?', 'Cơ chế hở hoặc kín và nguyên nhân gây ra.', 'Mức độ nhiễm khuẩn: sạch, sạch-nhiễm, nhiễm, bẩn.', 'Tính chất cấp tính (chấn thương, phẫu thuật) và mạn tính.', 'Tình trạng có sự hiện diện của biofilm hay không.', 'C', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Tổ chức nào nhấn mạnh vai trò của "biofilm" trong việc làm chậm quá trình lành thương khi định nghĩa về vết thương?', 'CDC (Centers for Disease Control and Prevention).', 'WHO (World Health Organization).', 'NPIAP (National Pressure Injury Advisory Panel).', 'IWII (International Wound Infection Institute).', 'D', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Trong giai đoạn Cầm máu (Hemostasis), hiện tượng co mạch tức thì xảy ra do cơ chế nào?', 'Do sự giải phóng cytokine và yếu tố tăng trưởng.', 'Do tác động của thần kinh và thể dịch.', 'Do sự kết dính của tiểu cầu tạo nút tiểu cầu.', 'Do collagen nội mô kích hoạt đông máu.', 'B', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Một vết thương đang ở ngày thứ 2 sau tổn thương, có biểu hiện phù nề, thực bào vi khuẩn tích cực. Vết thương này đang ở giai đoạn nào?', 'Giai đoạn Cầm máu.', 'Giai đoạn Viêm.', 'Giai đoạn Tăng sinh.', 'Giai đoạn Tái tạo.', 'B', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_3', 'VT-11', 'Đặc điểm nào sau đây là trọng tâm của giai đoạn Tăng sinh (Proliferation) trong quá trình lành thương?', 'Collagen sắp xếp lại và tăng độ bền kéo đạt 80%.', 'Bạch cầu trung tính và đại thực bào di chuyển đến vết thương.', 'Hình thành mô hạt giàu mạch máu và tái biểu mô từ rìa.', 'Mạch máu thừa thoái triển và hình thành sẹo dai chắc.', 'C', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Theo mô hình TIME, chữ "E" (Edge) tập trung vào mục tiêu can thiệp nào?', 'Loại bỏ mô hoại tử và làm sạch nền vết thương.', 'Tối ưu hóa độ ẩm và kiểm soát dịch tiết/mùi.', 'Kiểm soát tình trạng viêm và phù nề tại chỗ.', 'Theo dõi rìa vết thương và kích thích biểu mô hóa.', 'D', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Trong khung chiến lược chăm sóc toàn diện, các can thiệp như "tăng cường cung cấp máu, oxy và giảm đau" thuộc vòng nào?', 'Vòng Trung tâm (TIME).', 'Vòng thứ 2 (Ưu tiên - can thiệp khẩn cấp).', 'Vòng thứ 3 (Dài hạn - tối ưu hóa yếu tố lành thương).', 'Vòng ngoài cùng (Toàn thân - Hành vi - Xã hội).', 'B', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Tiêu chí nào sau đây dùng để đánh giá mục tiêu chăm sóc ở mức độ "Toàn thân - hệ thống"?', 'Mô hạt đỏ tươi và người bệnh báo đau giảm.', 'Người bệnh tuân thủ thay băng và bỏ thuốc lá.', 'Chỉ số Albumin máu cải thiện và HbA1c ổn định.', 'Gia đình thực hiện đúng kỹ thuật chăm sóc vết thương.', 'C', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Thang điểm FLACC được khuyến cáo sử dụng để đánh giá mức độ đau cho đối tượng nào?', 'Người lớn và trẻ em từ 16 tuổi trở lên.', 'Trẻ em từ 3 đến 15 tuổi.', 'Trẻ em dưới 3 tuổi.', 'Người bệnh hôn mê hoặc không có khả năng giao tiếp.', 'C', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Khi đánh giá nền vết thương, sự hiện diện của "đường hầm" (tunnelling) thường cảnh báo điều gì?', 'Vết thương đang tiến triển lành thương tốt.', 'Sự chậm lành hoặc có tình trạng nhiễm trùng.', 'Quá trình tái biểu mô hóa đang diễn ra nhanh.', 'Nền vết thương đang có sự tưới máu quá mức.', 'B', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Tại sao lưu thông máu kém lại làm tăng nguy cơ nhiễm trùng vết thương?', 'Do làm tăng áp lực kéo dài lên mô vùng tổn thương.', 'Do cản trở việc vận chuyển bạch cầu và các yếu tố tăng trưởng.', 'Do kích thích sự hình thành quá mức của mô hoại tử.', 'Do làm giảm khả năng co mạch trong giai đoạn cầm máu.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_3', 'VT-11', 'Chỉ số xét nghiệm nào sau đây khi tăng cao sẽ trực tiếp chỉ ra tình trạng nhiễm trùng đang xảy ra?', 'Hemoglobin (Hb).', 'Số lượng tiểu cầu.', 'Số lượng bạch cầu (WBC).', 'Nồng độ Albumin máu.', 'C', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Nồng độ Albumin máu thấp ảnh hưởng như thế nào đến quá trình lành thương?', 'Làm giảm lượng oxy vận chuyển đến vị trí vết thương.', 'Làm giảm nguồn protein cần thiết để sửa chữa mô.', 'Gây ra tình trạng kiểm soát đường huyết kém.', 'Làm suy giảm chức năng thận và tích tụ độc tố.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_3', 'VT-11', 'Can thiệp điều dưỡng nào là ưu tiên cho chẩn đoán "Giảm tưới máu mô ngoại vi"?', 'Đổi tư thế mỗi 2 giờ và dùng đệm chống loét.', 'Tư vấn chế độ ăn giàu protein và bổ sung vi chất.', 'Đánh giá chỉ số ABI, màu sắc và nhiệt độ da.', 'Sử dụng gạc kháng khuẩn để loại bỏ mô hoại tử.', 'C', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_3', 'VT-11', 'Theo khuyến cáo của WHS và NPIAP, loại băng nào là lựa chọn nền tảng cho chăm sóc vết thương mạn tính/loét tỳ đè?', 'Gạc cotton thông thường.', 'Băng duy trì ẩm (Hydrocolloid, Foam, Alginate).', 'Băng gạc khô tẩm kháng sinh.', 'Gạc tẩm cồn hoặc oxy già.', 'B', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Dung dịch rửa vết thương nào sau đây KHÔNG được khuyến cáo do gây độc tế bào và làm chậm lành thương?', 'Nước muối sinh lý (NaCl 0,9%).', 'Polyhexanide (PHMB).', 'Oxy già (Hydrogen peroxide).', 'Dung dịch làm sạch chuyên dụng không độc tế bào.', 'C', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Theo IWII, dung dịch Polyhexanide (PHMB) được ưu tiên sử dụng trong trường hợp nào?', 'Rửa vết mổ sạch ngay sau phẫu thuật.', 'Vết thương mạn tính, loét tỳ đè có biofilm.', 'Sát khuẩn vùng da lành xung quanh vết thương.', 'Thay thế nước muối sinh lý cho mọi loại vết thương hở.', 'B', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Loại băng nào có khả năng cầm máu và được khuyến cáo cho vết thương tiết dịch nhiều?', 'Hydrogel.', 'Hydrocolloid.', 'Alginate (từ tảo biển).', 'Silicone sheets.', 'C', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Khuyến cáo quốc tế về việc sử dụng Hydrocolloid đối với vết mổ sạch là gì?', 'Khuyến cáo dùng rộng rãi vì giúp giữ ẩm tốt.', 'Không khuyến cáo vì giữ dịch có thể gây nhiễm trùng.', 'Chỉ dùng khi vết mổ có dấu hiệu nhiễm trùng rõ ràng.', 'Dùng để thay thế gạc vô khuẩn thấm hút truyền thống.', 'B', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Trong giai đoạn Trưởng thành (Remodeling), sản phẩm nào được khuyến cáo để phòng ngừa sẹo lồi?', 'Băng Foam (bọt polyurethane).', 'Băng Alginate tẩm bạc.', 'Tấm silicone (Silicone sheets) hoặc băng ép.', 'Gạc cotton khô che chắn vết thương.', 'C', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Liệu pháp hút áp lực âm (NPWT) KHÔNG được khuyến cáo sử dụng trong trường hợp nào?', 'Vết thương phức tạp sau phẫu thuật.', 'Các vết loét mạn tính khó lành.', 'Sử dụng như một loại "máy phun sương" hỗ trợ.', 'Vết thương có lượng dịch tiết quá nhiều.', 'C', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Nguyên tắc quan trọng nhất trong quản lý ống dẫn lưu màng phổi là gì?', 'Phải là hệ thống dẫn lưu hở để dịch thoát nhanh.', 'Kín, một chiều, vô khuẩn và hút liên tục có điều khiển.', 'Chỉ dẫn lưu dựa trên trọng lực, không dùng áp lực âm.', 'Thay túi chứa dịch mỗi 2 giờ để đảm bảo vô khuẩn.', 'B', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Khi chăm sóc người bệnh có ống dẫn lưu, điều dưỡng cần báo ngay cho bác sĩ nếu gặp tình trạng nào?', 'Dịch dẫn lưu giảm dần theo thời gian.', 'Người bệnh cảm thấy đau nhẹ tại vị trí đặt ống.', 'Màu sắc, tính chất dịch thay đổi bất thường (máu, mủ).', 'Vùng da xung quanh ống dẫn lưu khô ráo.', 'C', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Theo nguyên tắc kiểm soát đau sau phẫu thuật, phương pháp nào được coi là tối ưu nhất?', 'Chỉ dùng Opioids liều cao để cắt cơn đau nhanh chóng.', 'Kiểm soát đau đa phương thức (thuốc + không dùng thuốc).', 'Đợi đến khi bệnh nhân yêu cầu mới dùng thuốc giảm đau.', 'Ưu tiên các biện pháp tâm lý hơn là dùng thuốc tê vùng.', 'B', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Nhóm thuốc giảm đau nào thường được chỉ định cho mức độ đau nhẹ đến vừa?', 'Morphine và Fentanyl.', 'Paracetamol và NSAIDs.', 'Thuốc tê vùng (Epidural).', 'Các loại thuốc an thần liều thấp.', 'B', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Biến chứng nguy hiểm cần theo dõi sát khi sử dụng thuốc giảm đau nhóm Opioids là gì?', 'Xuất huyết tiêu hóa và suy thận.', 'Tụt huyết áp và đau đầu sau chọc dò.', 'Suy hô hấp, buồn nôn và táo bón.', 'Tăng thân nhiệt và co giật cơ học.', 'C', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Đối với vết thương bị bỏng, thực hành nào sau đây phù hợp với khuyến cáo quốc tế?', 'Rửa bằng oxy già để sát khuẩn sâu.', 'Dùng hydrogel để làm mát và giữ ẩm.', 'Sử dụng chiết xuất lô hội như liệu pháp chính.', 'Đắp gạc cotton khô để tránh nhiễm trùng.', 'B', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Đặc điểm sinh lý của sẹo trong giai đoạn Tái tạo/Trưởng thành là gì?', 'Mô hạt đỏ tươi, dễ chảy máu khi chạm vào.', 'Độ bền kéo của sẹo đạt khoảng 80% so với da ban đầu.', 'Collagen bắt đầu được tổng hợp bởi nguyên bào sợi.', 'Tăng tính thấm thành mạch và hình thành phù nề.', 'B', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Việc giáo dục người bệnh bỏ thuốc lá và hạn chế rượu bia thuộc nhóm yếu tố nào trong kế hoạch chăm sóc?', 'Yếu tố Toàn thân.', 'Yếu tố Hành vi.', 'Yếu tố Xã hội.', 'Yếu tố Mô học tại chỗ.', 'B', NULL, 'FOUNDATION'),
    ('BAI_3', 'VT-11', 'Tại sao cần tránh sử dụng gạc cotton khô cho vết thương đang trong giai đoạn tăng sinh?', 'Vì nó không có khả năng ngăn ngừa vi khuẩn xâm nhập.', 'Vì dễ dính vào mô mới, gây đau và tổn thương khi thay băng.', 'Vì nó làm tăng nguy cơ hình thành sẹo lồi và co kéo.', 'Vì nó gây độc cho các tế bào bạch cầu và đại thực bào.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_4', 'XK-15', 'Theo phân loại mức độ khẩn cấp, phẫu thuật gãy xương hở được xếp vào loại nào?', 'Phẫu thuật cấp cứu (Emergency)', 'Phẫu thuật khẩn (Urgent)', 'Phẫu thuật chương trình (Elective)', 'Phẫu thuật trì hoãn', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Phẫu thuật nhằm mục đích lấy mẫu mô để xác định bản chất bệnh lý được gọi là:', 'Phẫu thuật điều trị', 'Phẫu thuật giảm nhẹ', 'Phẫu thuật chẩn đoán', 'Phẫu thuật phục hồi', 'C', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Loại phẫu thuật nào sau đây được phân loại là "Phẫu thuật sạch – nhiễm"?', 'Mổ thoát vị bẹn không biến chứng', 'Mổ cắt ruột thừa chưa vỡ', 'Mổ chấn thương bụng có dịch tiêu hóa', 'Mổ áp xe vùng cụt', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Biến chứng tai biến đường thở (0,1–0,2%) thường gặp nhất ở phương pháp vô cảm nào?', 'Gây tê tủy sống', 'Gây tê ngoài màng cứng', 'Gây mê toàn thân', 'Gây tê tại chỗ', 'C', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Dấu hiệu sớm nhất để nhận biết biến chứng chảy máu ngay trên bàn mổ là:', 'Mạch chậm, huyết áp tăng', 'Máu thấm băng vết mổ', 'Máu chảy nhiều tại diện mổ, huyết áp tụt, mạch nhanh yếu', 'Thiếu niệu và da tím tái', 'C', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Tỷ lệ nôn và buồn nôn sau mổ (PONV) ở bệnh nhân gây mê toàn thân thường là:', '5 – 10%', '10 – 20%', '20 – 30%', '> 50%', 'C', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Biến chứng "Đau đầu sau chọc dò" là đặc trưng của phương pháp vô cảm nào?', 'Gây mê nội khí quản', 'Gây tê tĩnh mạch', 'Gây tê tủy sống', 'Gây tê tại chỗ vùng mổ', 'C', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Thuốc nào nếu ngừng đột ngột trước mổ có thể gây tình trạng suy tim mạch cấp?', 'Kháng sinh nhóm Mycin', 'Thuốc lợi tiểu Thiazide', 'Corticosteroids', 'Thuốc chống trầm cảm MAO', 'C', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Vì sao cần tháo răng giả lung lay cho bệnh nhân trước khi đặt ống nội khí quản?', 'Tránh nhiễm khuẩn vùng miệng', 'Ngăn ngừa nguy cơ tắc nghẽn đường thở', 'Tránh làm hỏng răng giả của bệnh nhân', 'Giúp bệnh nhân giao tiếp dễ dàng hơn', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Thời gian nhịn ăn uống tiêu chuẩn trước phẫu thuật (trừ trường hợp đặc biệt) là:', '2 – 4 giờ', '4 – 6 giờ.', '6 – 8 giờ.', '10 – 12 giờ', 'C', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Việc ký "Phiếu đồng ý phẫu thuật" phải được thực hiện vào thời điểm nào?', 'Sau khi bệnh nhân đã vào phòng mổ.', 'Ngay sau khi dùng thuốc tiền mê.', 'Trước khi dùng thuốc tiền mê.', 'Bất cứ khi nào bác sĩ phẫu thuật có mặt', 'C', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Đối với người già, việc đắp chăn bông khi vận chuyển đến phòng mổ nhằm mục đích:', 'Tạo sự kín đáo cho bệnh nhân.', 'Phòng tránh trầy xước da.', 'Tránh hạ thân nhiệt do lớp mỡ dưới da giảm.', 'Giảm lo âu cho bệnh nhân', 'C', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Trong giai đoạn hồi tỉnh (PACU), ưu tiên nhận định hàng đầu của điều dưỡng là:', 'Tình trạng vết mổ và dẫn lưu.', 'Mức độ đau theo thang điểm VAS.', 'Kiểm soát đường thở và hô hấp (ABC).', 'Khả năng vận động của các chi', 'C', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Một bệnh nhân có điểm Aldrete là 8, hành động nào của điều dưỡng là đúng nhất?', 'Chuyển bệnh nhân về khoa hậu phẫu ngay.', 'Tiếp tục theo dõi tại phòng hồi tỉnh.', 'Cho bệnh nhân xuất viện về nhà.', 'Yêu cầu bệnh nhân tập vận động chi', 'B', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_4', 'XK-15', 'Chỉ số nào sau đây KHÔNG nằm trong hệ thống cảnh báo sớm NEWS?', 'Nhịp thở và SpO2.', 'Huyết áp tâm trương.', 'Huyết áp tâm thu.', 'Lượng nước tiểu mỗi giờ', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Theo hệ thống NEWS, điểm màu ĐỎ yêu cầu điều dưỡng phải:', 'Tăng tần suất theo dõi mỗi 4 giờ.', 'Thông báo cho bác sĩ nội trú đơn thuần.', 'Thông báo cho Đội phản ứng nhanh và bác sĩ nội trú.', 'Chỉ cần ghi chép vào hồ sơ theo dõi', 'C', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Biến chứng muộn (vài ngày đến vài tuần) sau mổ thường gặp nhất ở bệnh nhân bất động lâu là:', 'Suy hô hấp cấp.', 'Chảy máu thứ phát.', 'Huyết khối tĩnh mạch sâu (DVT).', 'Sốc phản vệ', 'C', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Nguyên tắc "An toàn" trong chăm sóc hậu phẫu được thể hiện qua hành động nào?', 'Sử dụng thang điểm để đánh giá đau.', 'Kiểm tra đúng người bệnh, đúng thuốc, đúng liều.', 'Giải thích kế hoạch chăm sóc cho bệnh nhân.', 'Phối hợp với chuyên gia dinh dưỡng', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Việc hướng dẫn bệnh nhân dùng tay hoặc gối đỡ vết mổ khi ho nhằm mục đích gì?', 'Giúp vết mổ nhanh liền.', 'Giảm đau và tránh bục vết mổ (mổ bụng/ngực).', 'Giữ vệ sinh cho băng vết mổ.', 'Tăng cường oxy cho phổi', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Quy trình điều dưỡng được coi là "ngôn ngữ khoa học" vì lý do nào sau đây?', 'Dựa hoàn toàn vào kinh nghiệm lâu năm.', 'Có cấu trúc 5 bước, logic và được công nhận toàn cầu.', 'Giúp bác sĩ ra y lệnh nhanh hơn.', 'Chỉ áp dụng cho các ca mổ phức tạp', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Loại phẫu thuật nào sau đây là phẫu thuật "Bẩn" (Dirty surgery)?', 'Mổ cắt ruột thừa chưa vỡ.', 'Mổ viêm phúc mạc do ruột thừa vỡ.', 'Mổ chấn thương bụng kín đơn thuần.', 'Mổ sỏi túi mật theo chương trình', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Kháng sinh nhóm Mycin khi kết hợp với thuốc giãn cơ có thể gây ra tai biến:', 'Sốc phản vệ tức thì.', 'Ngưng thở do liệt cơ hô hấp quá mức.', 'Tăng huyết áp kịch phát.', 'Suy thận cấp tính', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Trong nhận định hệ thống, việc đánh giá tri giác (Glasgow/AVPU) nhằm phát hiện sớm:', 'Nhiễm trùng vết mổ.', 'Thiếu oxy não hoặc biến chứng gây mê.', 'Tình trạng liệt ruột sau mổ.', 'Mức độ đau của bệnh nhân', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Vai trò "Người phối hợp" của điều dưỡng khi chuẩn bị xuất viện được thể hiện qua:', 'Hướng dẫn thay băng tại nhà.', 'Liên hệ với bác sĩ, dược sĩ đảm bảo sự liên tục chăm sóc.', 'Đánh giá khả năng tự chăm sóc của bệnh nhân.', 'Trấn an tinh thần bệnh nhân', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Dấu hiệu lâm sàng của "Bí tiểu" sau mổ thường là:', 'Đi tiểu rắt, nước tiểu màu hồng.', 'Căng tức bàng quang, đau bụng dưới, không đi tiểu được.', 'Nước tiểu có mủ và mùi hôi.', 'Lượng nước tiểu > 2000ml/24h', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Mục tiêu chính của phẫu thuật phục hồi (Reconstructive surgery) là:', 'Loại bỏ khối u ác tính.', 'Cải thiện ngoại hình thuần túy.', 'Khôi phục hình dạng hoặc chức năng bị mất.', 'Dẫn lưu dịch giảm triệu chứng', 'C', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Nhận định hệ tiêu hóa sau mổ, dấu hiệu nào gợi ý bệnh nhân bị liệt ruột?', 'Bụng mềm, có tiếng nhu động ruột.', 'Bụng chướng, không trung tiện, buồn nôn.', 'Bệnh nhân thấy đói và muốn ăn lỏng.', 'Vết mổ khô, không rỉ dịch', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Lập kế hoạch xuất viện cho người bệnh nên được bắt đầu từ khi nào?', 'Ngay khi bệnh nhân nhập viện.', '1 ngày trước khi bệnh nhân ra viện.', 'Ngay sau khi ca mổ kết thúc an toàn.', 'Khi bệnh nhân đã tự đi lại được', 'A', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Theo thang điểm Aldrete, tiêu chí "Tuần hoàn" được chấm 2 điểm khi:', 'HA biến động +/- 20-50 mmHg so với trước PT.', 'HA ổn định +/- 20 mmHg so với trước PT.', 'HA tụt sâu > 50 mmHg so với trước PT.', 'Mạch nhanh trên 100 lần/phút', 'B', NULL, 'FOUNDATION'),
    ('BAI_4', 'XK-15', 'Biến chứng muộn "Nhiễm trùng vết mổ" ở phẫu thuật nhiễm có tỷ lệ khoảng:', '2–5%.', '5–10%.', '10–20%.', '30–40%', 'C', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Theo WAO Update 2020, đặc điểm nào sau đây là quan trọng nhất trong định nghĩa đơn giản hóa về phản vệ?', 'Luôn phải có biểu hiện ở da và niêm mạc.', 'Là phản ứng cấp tính, đe dọa tính mạng có sự tham gia của hệ hô hấp hoặc tuần hoàn.', 'Phản ứng chỉ xảy ra khi có sự kết hợp giữa IgE và dị nguyên.', 'Chỉ được chẩn đoán khi có tình trạng tụt huyết áp rõ rệt.', 'B', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Theo Thông tư 51/2017/TT-BYT, Sốc phản vệ được xếp vào mức độ nào?', 'Độ II (Nặng).', 'Độ III (Nguy kịch).', 'Độ IV (Ngừng tuần hoàn).', 'Tùy thuộc vào tốc độ xuất hiện triệu chứng.', 'B', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Trong cơ chế bệnh sinh hiện đại sốc phản vệ, hiện tượng thoát dịch (Fluid Leak) có thể khiến bao nhiêu phần trăm thể tích huyết áp thoát ra khỏi lòng mạch trong 10 phút đầu?', '10 - 20%.', '20 - 35%.', '35 - 50%.', 'Trên 60%.', 'C', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', '"Empty Heart Syndrome" (Hội chứng buồng tim trống) xảy ra trên người bệnh phản vệ do cơ chế nào chính yếu?', 'Co thắt mạch vành đột ngột do Adrenaline.', 'Máu ứ trệ ở ngoại vi không về tim kịp khi thay đổi tư thế đột ngột.', 'Tăng áp lực keo quá mức trong lòng mạch.', 'Suy chức năng cơ tim do nồng độ Cytokine quá cao.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_5', 'CC-12', 'Tác động của Adrenaline lên thụ thể Alpha-1 giúp cải thiện tình trạng nào trong phản vệ?', 'Giãn cơ trơn phế quản.', 'Co mạch, nâng huyết áp và giảm phù nề niêm mạc.', 'Tăng co bóp cơ tim và nhịp tim.', 'Ức chế tế bào Mast giải phóng hóa chất trung gian.', 'B', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Phản vệ pha hai (Biphasic) thường có đỉnh điểm tái phát triệu chứng vào thời điểm nào sau khi đã ổn định?', '1 - 4 giờ.', '8 - 10 giờ.', '24 - 48 giờ.', 'Sau 72 giờ.', 'B', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Đặc điểm phân biệt chính của phản vệ KHÔNG qua trung gian IgE so với qua IgE là gì?', 'Triệu chứng lâm sàng nặng nề hơn.', 'Cần có giai đoạn mẫn cảm ở lần tiếp xúc đầu tiên.', 'Có thể xảy ra ngay ở lần tiếp xúc đầu tiên với tác nhân.', 'Chỉ xảy ra với các tác nhân là thực phẩm.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_5', 'CC-12', 'Bệnh nhân sau khi tiêm kháng sinh xuất hiện mề đay kèm theo đau bụng dữ dội và nôn. Theo Thông tư 51, trường hợp này phân độ là gì?', 'Độ I.', 'Độ II.', 'Độ III.', 'Theo dõi phản ứng có hại của thuốc.', 'B', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_5', 'CC-12', 'Triệu chứng nào sau đây là dấu hiệu chỉ điểm phản vệ Độ III (Nguy kịch) về mặt hô hấp?', 'Ngứa họng, chảy nước mũi.', 'Khó thở nhẹ, thở nhanh.', 'Tiếng rít thanh quản, khàn tiếng.', 'Ho khan từng cơn.', 'C', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Trong cấp cứu sốc phản vệ, vị trí tiêm bắp Adrenaline được ưu tiên nhất là mặt trước bên đùi vì lý do gì?', 'Ít gây đau cho bệnh nhân nhất.', 'Dễ thực hiện và ít chạm vào thần kinh, mạch máu lớn.', 'Giúp nồng độ Adrenaline trong máu đạt đỉnh nhanh nhất.', 'Tránh được tác dụng phụ gây hoại tử chi.', 'C', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Trong cấp cứu sốc phản vệ, liều Adrenaline tiêm bắp ban đầu được khuyến cáo cho người lớn là bao nhiêu?', '1 ống 1mg.', '1/2 ống 1mg.', '0,3mg tiêm dưới da.', '1/4 ống 1mg.', 'B', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Trong cấp cứu sốc phản vệ, nếu triệu chứng không cải thiện sau liều Adrenaline đầu tiên, thời gian nhắc lại liều tiếp theo theo quy định của Bộ Y tế Việt Nam là:', 'Sau mỗi 1 - 2 phút.', 'Sau mỗi 3 - 5 phút.', 'Sau mỗi 5 - 10 phút.', 'Sau mỗi 15 phút.', 'B', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Thuốc nào sau đây được sử dụng khi bệnh nhân phản vệ đang dùng thuốc chẹn Beta (Beta-blocker) mà không đáp ứng với Adrenaline?', 'Methylprednisolon.', 'Diphenhydramin.', 'Glucagon.', 'Salbutamol khí dung.', 'C', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_5', 'CC-12', 'Theo EAACI 2021/2022, chẩn đoán phản vệ có thể được thiết lập ngay cả khi:', 'Chỉ có duy nhất tình trạng tụt huyết áp sau tiếp xúc tác nhân nghi ngờ.', 'Phải có ít nhất 3 hệ cơ quan bị ảnh hưởng.', 'Triệu chứng da niêm mạc phải xuất hiện trước.', 'Có kết quả xét nghiệm IgE đặc hiệu dương tính.', 'A', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Trong xử trí tuần hoàn, lượng dịch Natri Clorid 0,9% bồi phụ nhanh cho người lớn bị sốc phản vệ thường là:', '500ml.', '1 - 2 lít.', '3 - 5 lít.', 'Tùy thuộc vào lượng nước tiểu.', 'B', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Vai trò của thuốc Antihistamine và Corticoid trong cấp cứu phản vệ là gì?', 'Là thuốc hàng thứ nhất, dùng ngay cùng Adrenaline.', 'Thay thế được Adrenaline trong trường hợp phản vệ Độ II.', 'Là thuốc hàng thứ hai, dùng để kiểm soát triệu chứng da và ngăn ngừa pha muộn.', 'Thuốc tiên quyết để đảo ngược tình trạng co thắt phế quản.', 'C', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Một bệnh nhân phản vệ đang nôn mửa, tư thế điều dưỡng cần đặt bệnh nhân là:', 'Nằm ngửa đầu thấp, chân cao.', 'Nằm nghiêng trái, đầu thấp.', 'Nằm ngửa, kê gối dưới vai.', 'Ngồi tư thế Fowler.', 'B', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_5', 'CC-12', 'Thời gian theo dõi bệnh nhân phản vệ tối thiểu tại cơ sở y tế sau khi ổn định là bao lâu?', '6 giờ.', '12 giờ.', '24 giờ.', '48 giờ.', 'C', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Chẩn đoán điều dưỡng ưu tiên hàng đầu khi bệnh nhân có phù Quinke vùng họng là gì?', 'Giảm tưới máu mô.', 'Nguy cơ tử vong liên quan đến tắc nghẽn đường thở cấp tính.', 'Lo âu mức độ nặng.', 'Thiếu hụt thể tích dịch.', 'B', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_5', 'CC-12', 'Mục tiêu kết quả (NOC) cho chẩn đoán "Giảm tưới máu mô ngoại vi" trong phản vệ là:', 'Nhịp thở 16 - 20 lần/phút.', 'Huyết áp tâm thu > 90 mmHg, chi ấm, CRT < 2s.', 'Bệnh nhân bớt lo sợ và bình tĩnh.', 'SpO2 đạt trên 94%.', 'B', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_5', 'CC-12', 'Theo Thông tư 51, thuốc nào KHÔNG được phép thử phản ứng (test) trừ khi có chỉ định đặc biệt của bác sĩ?', 'Chỉ có kháng sinh nhóm Penicillin.', 'Tất cả các loại thuốc.', 'Chỉ các thuốc gây mê.', 'Chỉ các loại vaccine.', 'B', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Tác dụng của Adrenaline lên thụ thể Beta-2 trên tế bào Mast giúp:', 'Tăng nhịp tim.', 'Giãn cơ trơn phế quản.', 'Ức chế giải phóng các hóa chất trung gian.', 'Co các tiểu động mạch.', 'C', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Khi thực hiện kế hoạch chăm sóc cho bệnh nhân sốc phản vệ, điều dưỡng cần theo dõi lượng nước tiểu mỗi giờ với mục tiêu đạt tối thiểu:', '0,2 ml/kg/giờ.', '0,5 ml/kg/giờ.', '1,0 ml/kg/giờ.', '2,0 ml/kg/giờ.', 'B', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Nguyên nhân gây phản vệ phổ biến nhất trong môi trường bệnh viện là:', 'Thực phẩm.', 'Nọc côn trùng.', 'Thuốc (đặc biệt là kháng sinh nhóm Beta-lactam).', 'Phấn hoa.', 'C', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Trong cấp cứu sốc phản vệ, tại sao việc dùng thuốc bổ trợ (Corticoid, Dimedrol) trước Adrenaline lại bị coi là nguy hiểm?', 'Vì gây tương tác thuốc làm giảm hiệu quả Adrenaline.', 'Vì làm chậm trễ thời gian vàng sử dụng Adrenaline để cứu sống bệnh nhân.', 'Vì gây tụt huyết áp nặng hơn.', 'Vì làm tăng nguy cơ phản ứng pha hai.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_5', 'CC-12', 'Trong giáo dục sức khỏe cho người bệnh bị phản vệ, điều gì là quan trọng nhất bệnh nhân cần thực hiện sau khi ra viện?', 'Mua sẵn thuốc Corticoid để tại nhà.', 'Luôn mang theo thẻ dị ứng và cung cấp thông tin này cho nhân viên y tế lần sau.', 'Tự thử phản ứng thuốc tại nhà trước khi uống.', 'Hạn chế vận động mạnh trong 1 tháng.', 'B', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Báo cáo phản ứng có hại của thuốc (ADR) khi xảy ra phản vệ cần gửi về đâu?', 'Sở Y tế địa phương.', 'Trung tâm Quốc gia về Thông tin Thuốc và Theo dõi phản ứng có hại của thuốc.', 'Viện Vệ sinh Dịch tễ Trung ương.', 'Cục Quản lý Dược.', 'B', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Thành phần quan trọng nhất luôn phải có sẵn trên xe tiêm hoặc nơi sử dụng thuốc là:', 'Bộ đặt nội khí quản.', 'Máy đo huyết áp.', 'Hộp thuốc cấp cứu phản vệ.', 'Bình oxy.', 'C', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Theo WAO 2020, triệu chứng da niêm mạc trong phản vệ có đặc điểm:', 'Luôn là triệu chứng xuất hiện đầu tiên.', 'Thường xuyên xuất hiện nhưng không phải luôn luôn có.', 'Chỉ gặp trong phản vệ qua trung gian IgE.', 'Biến mất ngay sau khi tiêm Adrenaline 1 phút.', 'B', NULL, 'FOUNDATION'),
    ('BAI_5', 'CC-12', 'Một bệnh nhân phản vệ Độ II đã được xử trí ổn định, nhưng sau 8 giờ lại xuất hiện khó thở và mề đay. Đây được gọi là:', 'Phản vệ đơn pha.', 'Phản vệ kéo dài.', 'Phản vệ pha hai.', 'Tác dụng phụ của Adrenaline.', 'C', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_6', 'XK-15', 'Theo quan điểm hiện đại (AO Foundation), bản chất của gãy xương được hiểu là:', 'Sự mất tính liên tục đơn thuần của cấu trúc xương.', 'Một tổn thương hệ thống gây phản ứng viêm toàn thân.', 'Tổn thương khu trú tại xương và màng xương.', 'Sự gián đoạn cấu trúc cơ học của thân xương.', 'B', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Tại sao gãy xương kín lại có nguy cơ chèn ép khoang cao hơn gãy xương hở?', 'Do lực chấn thương trong gãy kín thường mạnh hơn.', 'Do màng xương trong gãy kín không bị rách.', 'Do máu tụ và dịch phù nề không có chỗ thoát ra ngoài.', 'Do gãy kín thường xảy ra ở các vùng cơ dày.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_6', 'XK-15', 'Đặc điểm nào sau đây phân biệt gãy cành tươi (Greenstick) với các loại gãy xương khác?', 'Xương bị vỡ thành nhiều mảnh nhỏ dưới tác động lực mạnh.', 'Đường gãy nằm ngang và vuông góc hoàn toàn với trục xương.', 'Xương chỉ gãy một bên vỏ và uốn cong ở bên còn lại.', 'Đường gãy chạy xoắn ốc dọc theo thân xương.', 'C', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Trong các dấu hiệu lâm sàng sau, dấu hiệu nào là bằng chứng "chắc chắn" của gãy xương?', 'Đau chói tại điểm gãy khi thăm khám.', 'Mất khả năng vận động tự nhiên của chi.', 'Tiếng lạo xạo xương khi hai đầu gãy cọ vào nhau.', 'Tình trạng sưng nề và bầm tím lan rộng.', 'C', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Tại sao điều dưỡng không được cố tình tìm dấu hiệu lạo xạo xương khi thăm khám?', 'Vì dấu hiệu này không có giá trị chẩn đoán cao.', 'Vì có thể gây đau đớn dữ dội và dẫn đến sốc chấn thương.', 'Vì sẽ làm rách thêm màng xương và gây chảy máu.', 'Vì làm tăng nguy cơ nhiễm trùng từ bên ngoài.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_6', 'XK-15', 'Nguyên tắc "Số 2" trong chẩn đoán X-quang gãy xương bao gồm:', '2 bình diện, 2 khớp, 2 thời điểm.', '2 vị trí, 2 phim chụp, 2 bác sĩ đọc.', '2 tư thế, 2 loại tia, 2 vùng đối xứng.', '2 lần chụp, 2 kỹ thuật, 2 phim thẳng.', 'A', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Trường hợp gãy xương kín đáo (như xương thuyền), nếu X-quang lần đầu âm tính thì cần xử trí gì?', 'Chụp lại ngay lập tức với cường độ tia cao hơn.', 'Loại trừ hoàn toàn gãy xương và cho BN vận động.', 'Chụp lại sau 7-10 ngày khi có hiện tượng tiêu xương.', 'Chỉ định chụp CT-Scanner ngay để xác định.', 'C', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_6', 'XK-15', 'Thứ tự ưu tiên hàng đầu trong sơ cứu bệnh nhân đa chấn thương có gãy xương là:', 'Bất động ổ gãy bằng nẹp cứng.', 'Kiểm tra mạch và thần kinh ngoại vi.', 'Xử trí theo sơ đồ A-B-C-D-E (Ưu tiên tính mạng).', 'Giảm đau và chống sốc bằng thuốc.', 'C', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Nguyên tắc bất động xương gãy bằng nẹp tại hiện trường là:', 'Nắn chỉnh xương về vị trí giải phẫu trước khi đặt nẹp.', 'Bất động trên một khớp và dưới một khớp của ổ gãy.', 'Buộc nẹp thật chặt để đảm bảo không có cử động.', 'Chỉ đặt nẹp khi đã loại trừ tổn thương mạch máu.', 'B', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Việc kiểm tra mạch và thần kinh ngoại vi trong sơ cứu gãy xương phải thực hiện khi nào?', 'Ngay sau khi đưa bệnh nhân vào bệnh viện.', 'Sau khi đã hoàn tất việc bất động chi thể.', 'Cả trước và sau khi thực hiện bất động.', 'Chỉ khi bệnh nhân than tê hoặc mất cảm giác.', 'C', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Trong xử trí vết thương gãy hở, điều nào sau đây là SAI?', 'Không rửa dung dịch sát khuẩn mạnh trực tiếp vào ổ gãy.', 'Đặt Garo ngay lập tức cho mọi trường hợp có vết thương.', 'Phủ gạc vô khuẩn hoặc vải sạch lên vết thương.', 'Băng ép nếu có tình trạng chảy máu mạch máu.', 'B', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Kỹ thuật vận chuyển "Log-roll" (lăn gỗ) được chỉ định ưu tiên khi:', 'Bệnh nhân bị gãy nhiều xương dài cùng lúc.', 'Nghi ngờ có chấn thương cột sống kèm theo.', 'Bệnh nhân đang trong tình trạng sốc mất máu.', 'Cần di chuyển bệnh nhân từ cáng vào bồn tắm.', 'B', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Nhược điểm lớn nhất của phương pháp điều trị bảo tồn bằng bó bột là:', 'Chi phí điều trị quá cao so với phẫu thuật.', 'Nguy cơ nhiễm trùng vết mổ và mất máu.', 'Nguy cơ chèn ép khoang, teo cơ và cứng khớp.', 'Không giữ được trục xương thẳng khi kéo.', 'C', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Phương pháp kéo xuyên xương (Traction) có đặc điểm nào dưới đây?', 'Sử dụng lực kéo nhẹ qua băng dính dán lên da.', 'Chỉ áp dụng cho các gãy xương nhỏ, không di lệch.', 'Dùng đinh xuyên qua xương để kéo với lực mạnh, dài hạn.', 'BN có thể vận động sớm ngay sau khi đặt tạ kéo.', 'C', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Chỉ định ưu tiên của phương pháp cố định ngoài (External Fixation) là:', 'Gãy xương dài đơn thuần ở người trẻ tuổi.', 'Gãy xương hở độ nặng hoặc bệnh nhân đa chấn thương.', 'Gãy xương gần khớp cần nắn chỉnh tuyệt đối.', 'Mọi trường hợp gãy xương không thể bó bột.', 'B', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Biến chứng nào sau đây được xếp vào nhóm biến chứng "Tức thì" (Vài giờ đầu)?', 'Hội chứng chèn ép khoang.', 'Hội chứng tắc mạch mỡ (FES).', 'Sốc chấn thương (mất máu, sốc đau).', 'Viêm xương tủy mãn tính.', 'C', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Một bệnh nhân gãy xương đùi đơn thuần có thể mất khoảng bao nhiêu máu vào ổ gãy?', '100 - 500 ml.', '500 - 800 ml.', '1000 - 1500 ml.', 'Trên 2500 ml.', 'C', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Chu trình sinh lý bệnh của Hội chứng chèn ép khoang là:', 'Thiếu máu -> Phù nề -> Tăng áp lực nội khoang -> Xẹp mao mạch.', 'Mất máu -> Hạ huyết áp -> Co mạch ngoại vi -> Hoại tử cơ.', 'Vi khuẩn xâm nhập -> Phản ứng viêm -> Hình thành Biofilm.', 'Mỡ giải phóng -> Tắc mạch phổi -> Suy hô hấp cấp.', 'A', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_6', 'XK-15', 'Dấu hiệu lâm sàng điển hình nhất của Hội chứng chèn ép khoang là:', 'Mất mạch ngoại vi hoàn toàn.', 'Da chi tổn thương nhợt nhạt và lạnh.', 'Đau quá mức, tăng khi vận động thụ động ngón chi.', 'Xuất hiện các nốt xuất huyết vùng ngực, nách.', 'C', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Tam chứng lâm sàng của Hội chứng tắc mạch mỡ (FES) bao gồm:', 'Đau, Liệt, Mất mạch.', 'Suy hô hấp, Thay đổi ý thức, Nốt xuất huyết.', 'Sưng, Nóng, Đỏ đau tại vết thương.', 'Mạch nhanh, Tụt huyết áp, Da lạnh.', 'B', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Độc tính của Acid béo tự do trong Hội chứng tắc mạch mỡ gây ra tình trạng gì?', 'Tắc nghẽn cơ học tại các mao mạch lớn.', 'Phá hủy Surfactant gây suy hô hấp cấp (ARDS).', 'Kích hoạt quá trình tăng đông máu hệ thống.', 'Gây tiêu xương tại vị trí đầu gãy.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_6', 'XK-15', 'Tam chứng Virchow giải thích cơ chế của biến chứng nào?', 'Sốc chấn thương.', 'Hội chứng chèn ép khoang.', 'Thuyên tắc huyết khối tĩnh mạch (VTE).', 'Chậm liền xương và khớp giả.', 'C', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Trong quy tắc 6P, chữ "P" nào đại diện cho tình trạng rối loạn nhiệt độ?', 'Pain.', 'Pallor.', 'Paresthesia.', 'Poikilothermia.', 'D', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Can thiệp điều dưỡng ưu tiên để giảm phù nề chi tổn thương là:', 'Chườm nóng liên tục vùng chi sưng.', 'Nâng cao chi tổn thương hơn mức tim 10-15 cm.', 'Băng ép thật chặt vùng đang sưng nề.', 'Cho bệnh nhân vận động mạnh để tăng tuần hoàn.', 'B', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_6', 'XK-15', 'Dấu hiệu nào gợi ý bệnh nhân có nguy cơ thiếu hụt thể tích dịch (Sốc mất máu)?', 'Mạch chậm, huyết áp tăng cao.', 'Da hồng ấm, bệnh nhân tỉnh táo.', 'Mạch nhanh nhỏ, huyết áp tụt hoặc kẹt.', 'Lượng nước tiểu > 1ml/kg/giờ.', 'C', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Để dự phòng biến chứng teo cơ, cứng khớp trong bột, điều dưỡng nên hướng dẫn BN:', 'Cố gắng cử động các khớp bên trong lớp bột.', 'Tập gồng cơ (Isometric) định kỳ hàng ngày.', 'Tự ý cắt bớt các mép bột để cử động dễ hơn.', 'Tháo bột tạm thời để tập vận động mỗi ngày.', 'B', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_6', 'XK-15', 'Mục tiêu quan trọng nhất của việc sử dụng tất áp lực y khoa trong chăm sóc gãy xương là:', 'Giảm đau chói tại điểm gãy xương.', 'Dự phòng thuyên tắc huyết khối tĩnh mạch (VTE).', 'Giữ ấm cho chi bị tổn thương.', 'Cố định vững chắc ổ gãy xương.', 'B', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Biến chứng muộn nào thường gặp ở người hút thuốc lá hoặc bị tiểu đường?', 'Hội chứng chèn ép khoang.', 'Chậm liền xương hoặc không liền xương.', 'Hội chứng tắc mạch mỡ.', 'Sốc đau tức thì.', 'B', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Hình ảnh X-quang nào sau đây được coi là điển hình của gãy xương?', 'Hình ảnh vỏ xương dày lên bất thường.', 'Đường sáng mất tính liên tục của vỏ xương.', 'Hình ảnh mờ đều toàn bộ vùng thân xương.', 'Khoảng cách giữa các khớp thu hẹp lại.', 'B', NULL, 'FOUNDATION'),
    ('BAI_6', 'XK-15', 'Khi giáo dục sức khỏe cho BN bó bột, dấu hiệu nào cần dặn BN quay lại viện ngay?', 'Lớp bột bị bám bẩn nhẹ bên ngoài.', 'BN cảm thấy ngứa dưới lớp bột.', 'Các ngón chi bị tím, lạnh hoặc đau tăng đột ngột.', 'BN muốn thay đổi màu sắc của thạch cao.', 'C', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Theo định nghĩa hiện đại của WSES (2022), tắc ruột được nhìn nhận là:', 'Sự ngưng trệ lưu thông đơn thuần của dịch và hơi trong lòng ruột.', 'Một trạng thái cấp cứu bụng động học dẫn đến suy giảm tưới máu và phản ứng viêm hệ thống.', 'Một hội chứng chỉ xảy ra khi có vật cản cơ học trong lòng ống tiêu hóa.', 'Sự bế tắc cơ học dẫn đến rối loạn nhu động ruột khu trú.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Tại sao ruột non dễ bị tắc bởi dị vật hoặc khối u nhỏ hơn so với đại tràng?', 'Vì ruột non có nhu động mạnh hơn.', 'Vì chiều dài ruột non lớn hơn nhiều so với đại tràng.', 'Vì đường kính lòng ruột non nhỏ hơn (2.5-3 cm so với 5-8 cm).', 'Vì hệ thống mạc treo ruột non lỏng lẻo hơn.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_7', 'XK-15', 'Mốc giải phẫu nào được coi là điểm hẹp nhất của ruột non, nơi bã thức ăn dễ bị kẹt lại?', 'Góc Treitz.', 'Góc đại tràng trái.', 'Van hồi manh tràng (Van Bauhin).', 'Các nếp phúc mạc hậu phẫu.', 'C', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Trong cơ chế tắc ruột thắt nghẹt (Strangulation), diễn tiến tổn thương mạch máu xảy ra như thế nào?', 'Động mạch bị ép trước gây hoại tử, tĩnh mạch bị ép sau gây sung huyết.', 'Tĩnh mạch bị ép trước gây sung huyết, động mạch bị ép sau gây hoại tử.', 'Cả động mạch và tĩnh mạch bị ép cùng lúc dẫn đến hoại tử khô.', 'Chỉ có các mao mạch thành ruột bị vỡ do áp lực lòng ruột quá cao.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_7', 'XK-15', 'Lượng dịch tiêu hóa đổ vào lòng ống tiêu hóa mỗi ngày để lưu thông bình thường là bao nhiêu?', '3 - 5 lít.', '5 - 7 lít.', '7 - 9 lít.', 'Trên 10 lít.', 'C', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Cơ chế chính dẫn đến sốc giảm thể tích trong tắc ruột dù bệnh nhân không mất máu ra ngoài là:', 'Do vi khuẩn xâm nhập vào máu gây giãn mạch.', 'Do nôn mửa quá nhiều làm mất nước.', 'Do dịch thoát vào "khoang thứ ba" (lòng ruột) và giảm hấp thu niêm mạc.', 'Do đau quá mức gây ức chế thần kinh giao cảm.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_7', 'XK-15', 'Tiếng reo vang nhu động (Borborygmi) xuất hiện trong giai đoạn nào của tắc ruột cơ học?', 'Giai đoạn muộn khi cơ ruột đã liệt hoàn toàn.', 'Giai đoạn đầu khi đoạn ruột trên điểm tắc tăng co bóp mạnh.', 'Chỉ xuất hiện trong tắc ruột cơ năng do rối loạn điện giải.', 'Giai đoạn khi bắt đầu có biến chứng viêm phúc mạc.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Sự tích tụ khí trong lòng ruột khi bị tắc có nguồn gốc chủ yếu từ đâu?', '70% do vi khuẩn lên men, 30% do nuốt vào.', '50% do nuốt vào, 50% do phản ứng hóa học trong ruột.', '70% do nuốt vào, 30% do vi khuẩn lên men và phản ứng hóa học.', 'Toàn bộ do sự ứ đọng và phân hủy thức ăn.', 'C', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Loại vi khuẩn nào phát triển bùng nổ và có nguy cơ xuyên thành cao nhất khi ruột bị tắc?', 'Vi khuẩn hiếu khí và tụ cầu.', 'Vi khuẩn kỵ khí và E. coli.', 'Vi khuẩn Gr (+) và xoắn khuẩn.', 'Các loại nấm men đường ruột.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Đặc điểm của tắc ruột cơ năng (liệt ruột) về mặt lâm sàng là:', 'Đau bụng quặn từng cơn, nhu động ruột âm sắc cao.', 'Bụng chướng đều, đau âm ỉ liên tục, nhu động ruột im lặng hoàn toàn.', 'Có dấu hiệu rắn bò và quai ruột nổi rõ dưới thành bụng.', 'Nôn mửa sớm và rầm rộ kèm theo sốt cao.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', '"Tắc ruột co thắt động học" (Dynamic/Spastic Ileus) thường gặp trong trường hợp nào?', 'Sau mổ bụng hoặc viêm phúc mạc.', 'Hạ Kali máu nặng.', 'Ngộ độc chì hoặc porphyria.', 'Xoắn ruột do dính.', 'C', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Triệu chứng nôn xuất hiện sớm và rầm rộ là đặc điểm của vị trí tắc nào?', 'Tắc ruột thấp (Đại tràng).', 'Tắc ruột cao (Ruột non).', 'Tắc ruột do liệt (Cơ năng).', 'Tắc ruột ở đoạn trực tràng.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Ruột sẽ bắt đầu bị hoại tử trong vòng bao nhiêu giờ nếu tình trạng thắt nghẹt mạch máu không được xử trí?', '2 giờ.', '6 giờ.', '12 giờ.', '24 giờ.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Trong pha 2 của cơ chế bệnh sinh, nôn mửa do tắc ruột cao (dạ dày/tá tràng) thường dẫn đến rối loạn kiềm toan nào?', 'Toan chuyển hóa (Metabolic acidosis).', 'Kiềm chuyển hóa (Metabolic alkalosis).', 'Toan hô hấp (Respiratory acidosis).', 'Kiềm hô hấp (Respiratory alkalosis).', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_7', 'XK-15', 'Tại sao tắc ruột muộn lại gây suy thận cấp trước thận?', 'Do độc tố vi khuẩn hủy hoại tế bào ống thận.', 'Do mất nước và điện giải dẫn đến cô đặc máu và giảm tưới máu thận.', 'Do tăng áp lực nội lòng ruột chèn ép trực tiếp vào niệu quản.', 'Do lạm dụng thuốc giảm đau gây độc cho thận.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_7', 'XK-15', 'Hiện tượng "xuyên thành vi khuẩn" (Translocation) xảy ra khi nào?', 'Ngay khi có vật cản cơ học xuất hiện.', 'Khi nhu động ruột tăng mạnh ở pha 1.', 'Khi hàng rào niêm mạc bị tổn thương do thiếu máu cục bộ và tăng áp lực.', 'Chỉ khi ruột đã bị thủng hoàn toàn vào ổ bụng.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_7', 'XK-15', 'Dấu hiệu nào là mấu chốt khẳng định sự ngưng trệ hoàn toàn lưu thông trong lòng ruột?', 'Đau bụng quặn cơn.', 'Nôn ra dịch mật.', 'Bí trung, đại tiện.', 'Bụng chướng căng.', 'C', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Dấu hiệu rắn bò (nhu động ruột nổi lên dưới thành bụng) là đặc trưng của loại tắc ruột nào?', 'Tắc ruột cơ năng.', 'Tắc ruột cơ học.', 'Tắc ruột thắt nghẹt giai đoạn muộn.', 'Viêm phúc mạc do thủng ruột.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Khi thăm trực tràng ở người bệnh tắc ruột, điều dưỡng thường nhận thấy:', 'Bóng trực tràng đầy phân cứng.', 'Bóng trực tràng rỗng (không có phân).', 'Có nhiều dịch nhầy lẫn máu tươi.', 'Cơ thắt hậu môn bị liệt hoàn toàn.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Hình ảnh X-quang bụng đứng có mức nước - mức hơi rộng hơn cao, xếp hình bậc thang từ hố chậu phải lên hạ sườn trái gợi ý:', 'Tắc đại tràng.', 'Tắc ruột non.', 'Liệt ruột sau mổ.', 'Thủng tạng rỗng.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Cận lâm sàng được coi là "Tiêu chuẩn vàng" để chẩn đoán vị trí, nguyên nhân và biến chứng tắc ruột hiện nay là:', 'X-quang bụng không chuẩn bị.', 'Siêu âm ổ bụng tổng quát.', 'Chụp cắt lớp vi tính (CT Scan) có tiêm thuốc cản quang.', 'Xét nghiệm Lactate máu.', 'C', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Chỉ số xét nghiệm nào tăng cao là dấu hiệu cảnh báo sớm tình trạng hoại tử ruột cần mổ gấp?', 'Urea và Creatinine.', 'Bilirubin trực tiếp.', 'Lactate máu.', 'Glucose máu.', 'C', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Biến chứng toàn thân nào thường xảy ra do bụng chướng căng đẩy cơ hoành lên cao?', 'Sốc nhiễm khuẩn.', 'Suy hô hấp cấp.', 'Suy thận cấp tại thận.', 'Toan chuyển hóa do mất dịch kiềm.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Mục đích quan trọng nhất của việc đặt ống thông dạ dày (Nasogastric Tube) trong điều trị tắc ruột là gì?', 'Để cung cấp chất dinh dưỡng cho người bệnh.', 'Để lấy mẫu dịch dạ dày đi xét nghiệm vi khuẩn.', 'Để giải tỏa áp lực, giảm chướng bụng và ngăn ngừa hít sặc.', 'Để bơm thuốc nhuận tràng vào đoạn dưới điểm tắc.', 'C', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Test thuốc cản quang Gastrografin thường được áp dụng cho trường hợp nào?', 'Tắc ruột do xoắn đại tràng Sigma.', 'Tắc ruột do dính không có dấu hiệu thắt nghẹt.', 'Tắc ruột cơ học do khối u đại tràng.', 'Thoát vị bẹn nghẹt.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Phương pháp bơm hơi tháo lồng thường được chỉ định cho đối tượng nào và thời điểm nào?', 'Người lớn bị lồng ruột do khối u.', 'Trẻ em từ 6 tháng đến 2 tuổi đến trước 24 - 48 giờ.', 'Bệnh nhân có dấu hiệu viêm phúc mạc rõ rệt.', 'Bệnh nhân lồng ruột đã có biến chứng thủng ruột.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Trong khám nhận định thực thể, âm sắc nhu động ruột "âm kim khí" (vang, cao) báo hiệu điều gì?', 'Ruột đã bị liệt hoàn toàn.', 'Giai đoạn đầu của tắc ruột cơ học.', 'Bệnh nhân đã thông suốt đường tiêu hóa.', 'Có dịch tự do trong ổ bụng.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Can thiệp điều dưỡng ưu tiên cho chẩn đoán "Mô hình thở không hiệu quả" do chướng bụng là:', 'Hướng dẫn bệnh nhân nhịn ăn hoàn toàn.', 'Hỗ trợ nằm tư thế Semi-Fowler (30-45 độ) và đặt sonde dạ dày.', 'Thực hiện thuốc giảm đau Morphine tĩnh mạch.', 'Vệ sinh răng miệng bằng nước muối sinh lý.', 'B', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_7', 'XK-15', 'Theo dõi bảng cân bằng dịch (In/Out) ở bệnh nhân tắc ruột cần thực hiện định kỳ bao lâu một lần?', 'Mỗi 24 giờ một lần vào buổi sáng.', 'Mỗi 4 - 8 giờ một lần.', 'Chỉ thực hiện khi bệnh nhân có biểu hiện tụt huyết áp.', 'Sau mỗi lần bệnh nhân nôn mửa.', 'B', NULL, 'FOUNDATION'),
    ('BAI_7', 'XK-15', 'Can thiệp nào giúp kích thích nhu động ruột trở lại sớm cho bệnh nhân sau mổ tắc ruột?', 'Cho bệnh nhân nằm yên tuyệt đối tại giường.', 'Khuyến khích vận động sớm và nhai kẹo cao su (theo y lệnh).', 'Cho bệnh nhân ăn cơm ngay sau khi tỉnh thuốc mê.', 'Truyền dịch tĩnh mạch tốc độ chậm.', 'B', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_8', 'XK-15', 'Theo quan điểm hiện đại (WSES 2020), viêm ruột thừa (VRT) được phân loại như thế nào?', 'Là một bệnh lý đồng nhất tiến triển theo thời gian.', 'Gồm hai thể riêng biệt: không biến chứng và có biến chứng.', 'Luôn tiến triển từ sung huyết sang hoại tử nếu không mổ.', 'Chỉ bao gồm các tình trạng viêm do tắc nghẽn lòng túi cùng.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Đặc điểm giải phẫu nào của ruột thừa là yếu tố then chốt dẫn đến hoại tử nhanh khi áp lực lòng tăng cao?', 'Là một ống "ngõ cụt" và lòng rất hẹp.', 'Nằm ở nơi hội tụ của 3 dải cơ dọc manh tràng.', 'Được cung cấp máu bởi động mạch tận.', 'Chứa một lượng lớn các nang bạch huyết dưới niêm mạc.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_8', 'XK-15', 'Nguyên nhân chính gây tắc nghẽn lòng ruột thừa dẫn đến VRT ở trẻ em thường là:', 'Sỏi phân (Fecaliths).', 'Dị vật hoặc ký sinh trùng (giun đũa).', 'Quá sản tổ chức bạch huyết.', 'Sự vặn xoắn tự nhiên của gốc ruột thừa.', 'C', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Ở độ tuổi nào các nang bạch huyết dưới niêm mạc ruột thừa phát triển đạt đỉnh, làm tăng nguy cơ VRT?', '5 - 10 tuổi.', '12 - 20 tuổi.', '20 - 30 tuổi.', '40 - 50 tuổi.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Khi bị tắc nghẽn, áp lực nội lòng ruột thừa có thể tăng vọt lên mức 50-65 mmHg. Hệ quả trực tiếp của mức áp lực này là gì?', 'Vượt quá áp lực tĩnh mạch gây ứ trệ tuần hoàn.', 'Vượt quá áp lực mao mạch dẫn đến thiếu máu và thủng.', 'Ngăn cản sự bài tiết dịch nhầy của niêm mạc.', 'Làm chết các vi khuẩn có lợi (Microbiome).', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_8', 'XK-15', 'Một bệnh nhân đau âm ỉ vùng thắt lưng phải, các nghiệm pháp bụng âm tính. Vị trí ruột thừa viêm nào cần được nghĩ tới đầu tiên?', 'Trong chậu hông.', 'Dưới gan.', 'Sau manh tràng.', 'Trước hồi tràng.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_8', 'XK-15', 'Cơn đau "di chuyển" (Murphy’s sign) trong VRT điển hình được mô tả là:', 'Đau khu trú ngay tại hố chậu phải từ lúc khởi phát.', 'Đau quanh rốn/thượng vị rồi khu trú về hố chậu phải sau 6-12h.', 'Đau khắp bụng sau đó khu trú ở vùng hạ sườn phải.', 'Đau từ vùng thắt lưng phải lan dần ra phía trước rốn.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Tại sao ở giai đoạn sớm của VRT, bệnh nhân thường cảm thấy đau mơ hồ vùng quanh rốn hoặc thượng vị?', 'Do vi khuẩn bắt đầu xâm nhập vào thành ruột thừa.', 'Do kích thích thần kinh thân thể chi phối phúc mạc thành.', 'Do kích thích thần kinh thực vật (tạng) chi phối lớp thanh mạc.', 'Do hiện tượng liệt ruột cơ năng làm chướng bụng.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_8', 'XK-15', 'Triệu chứng cơ năng nào xuất hiện ở gần 100% các trường hợp VRT, nếu thiếu cần xem xét lại chẩn đoán?', 'Nôn và buồn nôn.', 'Sốt cao kèm rét run.', 'Chán ăn.', 'Bí trung đại tiện.', 'C', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Điểm Lanz là vị trí đau gợi ý ruột thừa nằm ở đâu?', 'Sau manh tràng.', 'Trong chậu hông.', 'Dưới gan.', 'Sau hồi tràng.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Kỹ thuật khám "Ấn sâu vào hố chậu trái gây đau ở hố chậu phải" là dấu hiệu gì?', 'Dấu hiệu Blumberg.', 'Dấu hiệu Rovsing.', 'Dấu hiệu Dieulafoy.', 'Dấu hiệu Psoas.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Dấu hiệu Blumberg (Phản ứng dội) dương tính phản ánh tình trạng lâm sàng nào?', 'Ruột thừa bắt đầu bị tắc nghẽn lòng kín.', 'Có sự kích thích phúc mạc thành.', 'Đã có biến chứng vỡ gây viêm phúc mạc toàn thể.', 'Có sự tăng cảm giác da do viêm nhiễm trùng.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Triệu chứng "Bụng cứng như gỗ, không di động theo nhịp thở" là biểu hiện của:', 'Co thắt thành bụng (Muscular Defense).', 'Đám quánh ruột thừa.', 'Co cứng thành bụng (Rigidity).', 'Phản ứng dội (Blumberg).', 'C', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Thăm trực tràng thấy túi cùng Douglas đau chói (Tiếng kêu Douglas) có giá trị đặc biệt trong chẩn đoán thể VRT nào?', 'Thể sau manh tràng.', 'Thể dưới gan.', 'Thể chậu hông.', 'Thể trước hồi tràng.', 'C', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Nghiệm pháp cơ Thắt lưng chậu (Psoas sign) được thực hiện như thế nào và gợi ý vị trí nào?', 'Gấp gối và xoay trong đùi phải - Ruột thừa chậu hông.', 'Duỗi chân phải ra sau khi nằm nghiêng trái - Ruột thừa sau manh tràng.', 'Ấn sâu vùng hạ sườn phải khi hít vào - Ruột thừa dưới gan.', 'Dồn khí từ đại tràng trái sang phải - Ruột thừa bình thường.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Kết quả xét nghiệm máu nào sau đây cảnh báo nguy cơ cao ruột thừa đã có biến chứng vỡ hoặc hoại tử?', 'WBC 11.000/mm³ và CRP tăng nhẹ.', 'WBC > 18.000/mm³ kèm tăng bạch cầu đa nhân trung tính.', 'WBC bình thường nhưng CRP tăng rất cao.', 'Bạch cầu Lympho tăng chiếm ưu thế.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Biến chứng nào xảy ra khi các tạng xung quanh bao bọc ruột thừa vỡ tạo thành một túi mủ khu trú?', 'Viêm phúc mạc toàn thể.', 'Đám quánh ruột thừa.', 'Áp xe ruột thừa.', 'Sốc nhiễm khuẩn.', 'C', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Đặc điểm lâm sàng điển hình của Đám quánh ruột thừa là:', 'Khối hố chậu phải sưng, nóng, ấn đau chói, có dấu hiệu chạm sóng.', 'Khối hố chậu phải không di động, bề mặt nhẵn, ấn đau ít, cơn đau giảm dần.', 'Bụng cứng như gỗ kèm sốt cao rét run và môi khô lưỡi bẩn.', 'Đau dữ dội vùng hố chậu phải và có phản ứng thành bụng rõ.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Hướng xử trí ưu tiên đối với Đám quánh ruột thừa là:', 'Mổ cắt ruột thừa cấp cứu ngay lập tức.', 'Điều trị nội khoa kháng sinh tích cực (NOM).', 'Chọc hút mủ dưới hướng dẫn của siêu âm.', 'Thăm dò ổ bụng qua nội soi.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Ưu điểm của phẫu thuật nội soi so với mổ mở trong điều trị VRT là:', 'Không bao giờ xảy ra biến chứng nhiễm trùng vết mổ.', 'Ít đau sau mổ, hồi phục nhanh, thẩm mỹ cao.', 'Thời gian cuộc mổ luôn ngắn hơn mổ mở.', 'Không gây trướng bụng sau mổ.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Điều dưỡng cần theo dõi tình trạng đau vai phải sau mổ nội soi VRT là do:', 'Tổn thương thần kinh hoành trong lúc mổ.', 'Tư thế nằm của bệnh nhân trên bàn mổ không phù hợp.', 'Khí CO₂ còn sót lại trong ổ bụng sau mổ.', 'Biến chứng viêm túi mật cấp sau mổ.', 'C', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Tỷ lệ tái phát VRT trong vòng 1 năm sau khi điều trị nội khoa thành công bằng kháng sinh là khoảng:', '5 - 10%.', '20 - 30%.', '40 - 50%.', '70 - 80%.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Tư thế nằm nào thường được khuyến cáo cho bệnh nhân VRT để giảm sức căng cơ bụng và giảm đau?', 'Nằm ngửa phẳng, kê gối dưới đầu.', 'Nằm tư thế Fowler hoặc nằm nghiêng co chân phải.', 'Nằm sấp để giảm áp lực lên ruột thừa.', 'Nằm đầu thấp, chân cao để tăng tưới máu não.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Hành động nào sau đây bị TUYỆT ĐỐI cấm khi chăm sóc bệnh nhân nghi ngờ VRT chưa có chẩn đoán xác định?', 'Cho bệnh nhân uống nước khi thấy khô miệng.', 'Chườm nóng vùng bụng.', 'Đo dấu hiệu sinh tồn thường xuyên.', 'Đánh giá tính chất đau bụng.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Chỉ số lượng nước tiểu tối thiểu bao nhiêu cho thấy tình trạng bù dịch tiền phẫu hiệu quả?', '> 0.1 ml/kg/giờ.', '> 0.5 ml/kg/giờ.', '> 1.5 ml/kg/giờ.', '> 2.0 ml/kg/giờ.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Mục tiêu chính của việc hướng dẫn bệnh nhân nhai kẹo cao su sau mổ VRT (khi được phép) là gì?', 'Giảm cảm giác lo âu và căng thẳng.', 'Làm sạch răng miệng do phải nhịn ăn lâu.', 'Kích thích nhu động ruột, phòng ngừa liệt ruột.', 'Giảm tình trạng buồn nôn do tác dụng của thuốc mê.', 'C', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Theo quy trình chăm sóc hậu phẫu, khi nào bệnh nhân có thể bắt đầu được cho ăn từ lỏng đến đặc?', 'Ngay sau khi tỉnh mê và hết cảm giác buồn nôn.', 'Sau 12 giờ mổ đối với phẫu thuật nội soi.', 'Khi bệnh nhân đã có trung tiện.', 'Khi nghe thấy tiếng nhu động ruột tăng mạnh.', 'C', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Biến chứng "Liệt ruột cơ năng" sau mổ thường được nhận diện qua các dấu hiệu:', 'Vết mổ sưng đỏ, thấm dịch và sốt cao trở lại.', 'Bụng chướng, chưa có trung tiện, không nghe thấy nhu động ruột.', 'Đau tức vùng vai phải và bụng chướng nhẹ.', 'Đi tiểu ít, sẫm màu và niêm mạc miệng khô.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Sau khi ra viện, điều dưỡng cần tư vấn bệnh nhân tránh làm việc nặng trong khoảng thời gian bao lâu?', '1 tuần.', '2 - 4 tuần.', '2 - 3 tháng.', '6 tháng.', 'B', NULL, 'FOUNDATION'),
    ('BAI_8', 'XK-15', 'Cơ chế sinh lý bệnh cốt lõi của viêm ruột thừa là gì?', 'Nhiễm trùng máu lan đến ruột thừa.', 'Tắc nghẽn lòng kín (Closed-loop obstruction).', 'Sự xâm nhập đột ngột của ký sinh trùng.', 'Thoát vị bẹn nghẹt gây ảnh hưởng ruột thừa.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Theo quan điểm hiện đại (ACG & ESGE, 2021), yếu tố nào được nhấn mạnh nhất trong định nghĩa xuất huyết tiêu hóa (XHTH)?', 'Tình trạng máu thoát ra khỏi lòng mạch vào ống tiêu hóa.', 'Sự thay đổi màu sắc phân và chất nôn của người bệnh.', 'Trạng thái cấp cứu huyết động và tính chất tái phát.', 'Sự mất cân bằng giữa yếu tố tấn công và bảo vệ niêm mạc.', 'C', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Mốc giải phẫu dây chằng Treitz có ý nghĩa quan trọng nhất như thế nào trong phân loại XHTH?', 'Là điểm bắt đầu của hỗng tràng, nơi acid dạ dày bắt đầu bị trung hòa.', 'Là "đường biên giới" để phân chia XHTH trên và XHTH dưới.', 'Là vị trí thường xuyên xảy ra các ổ loét sâu vào động mạch vị tá tràng.', 'Là nơi đánh dấu điểm kết thúc của hệ thống tĩnh mạch cửa.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Tại sao trong XHTH cao, chỉ số Urea (BUN) thường tăng cao trong khi Creatinine vẫn bình thường (Tỷ lệ BUN/Creatinine > 30)?', 'Do thận bị suy cấp tính ngay lập tức sau khi mất máu.', 'Do vi khuẩn ruột phân hủy protein máu thành Amoniac rồi chuyển hóa thành Urea.', 'Do máu đóng vai trò là chất nhuận tràng làm giảm tái hấp thu nước tại thận.', 'Do cơ thể tăng cường chuyển hóa đường tại gan để bù đắp năng lượng.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_9', 'NK-14', 'Một bệnh nhân đi ngoài phân đen nhưng đóng thành khuôn. Điều này có ý nghĩa lâm sàng gì nhất?', 'Bệnh nhân đang có tình trạng chảy máu cấp tính dữ dội.', 'Máu đã tiếp xúc với Acid dạ dày trong thời gian rất ngắn.', 'Tình trạng chảy máu của bệnh nhân đã tạm thời ổn định.', 'Bệnh nhân bị XHTH thấp nhưng máu chảy chậm.', 'C', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_9', 'NK-14', 'Cơ chế gây vỡ tĩnh mạch thực quản ở bệnh nhân xơ gan là do:', 'Acid dạ dày ăn mòn trực tiếp vào các tĩnh mạch nằm nông ở thực quản.', 'Áp lực tĩnh mạch cửa tăng cao (>10-12 mmHg) dồn máu về các vòng nối.', 'Sự thiếu hụt Vitamin K làm thành mạch tĩnh mạch thực quản trở nên mỏng.', 'Áp lực tâm thất phải tăng cao gây ứ máu tại hệ thống tĩnh mạch thực quản.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_9', 'NK-14', 'Đặc điểm nào của hệ thống động mạch nuôi dưỡng hệ tiêu hóa làm cho các ổ loét thủng mạch máu lớn khó tự cầm?', 'Các tĩnh mạch đổ trực tiếp về tĩnh mạch cửa không qua van.', 'Hệ thống mao mạch dưới niêm mạc rất mỏng và nằm nông.', 'Các vòng cung mạch máu nối tiếp nhau rất phong phú và lưu lượng lớn.', 'Sự hiện diện của các yếu tố tấn công như Pepsin và Acid HCl.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_9', 'NK-14', 'Trong giai đoạn 3 của phản ứng hệ thống khi mất máu, tại sao chỉ số Hemoglobin (Hb) thường tụt dốc sau 1-2 giờ đầu?', 'Do hệ giao cảm gây co mạch ngoại vi làm hồng cầu bị phá hủy.', 'Do thận tiết Renin làm tăng đào thải hồng cầu qua nước tiểu.', 'Do cơ thể kéo dịch từ khoảng kẽ vào lòng mạch làm loãng máu.', 'Do gan ngưng tổng hợp Protein và Hemoglobin để tiết kiệm năng lượng.', 'C', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_9', 'NK-14', 'Bệnh nhân được phân loại XHTH mức độ trung bình khi lượng máu mất chiếm khoảng bao nhiêu thể tích tuần hoàn?', '< 15% thể tích tuần hoàn.', '15% - 30% thể tích tuần hoàn.', '30% - 40% thể tích tuần hoàn.', '> 40% thể tích tuần hoàn.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Chỉ số huyết động nào sau đây báo hiệu tình trạng XHTH mức độ nặng?', 'Mạch 110 lần/phút, HA tâm thu 95 mmHg.', 'Mạch 125 lần/phút, HA tâm thu < 90 mmHg.', 'Mạch 90 lần/phút, HA tâm thu ổn định.', 'Mạch nhỏ khó bắt nhưng HA tâm thu vẫn đạt 100 mmHg.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Tại sao bệnh nhân XHTH do xơ gan có nguy cơ cao bị hôn mê gan (Bệnh não gan)?', 'Do mất máu làm não thiếu oxy trường diễn.', 'Do gan không chuyển hóa được NH3 tạo ra từ protein máu trong ruột.', 'Do tình trạng hạ đường huyết đột ngột sau khi nôn máu.', 'Do nồng độ Urea trong máu tăng quá cao gây độc cho thần kinh.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_9', 'NK-14', '"Tiêu chuẩn vàng" để xác định vị trí, nguyên nhân và tiến hành cầm máu tại chỗ trong XHTH là:', 'Chụp CT-Scanner đa dãy (Multi-slice CT).', 'Đặt ống thông dạ dày (Sonde Nasogastric).', 'Nội soi tiêu hóa (Dạ dày hoặc Đại trực tràng).', 'Thăm trực tràng bằng tay (DRE).', 'C', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Mục đích chính của việc sử dụng thuốc ức chế bơm Proton (PPI) liều cao trong điều trị loét dạ dày chảy máu là:', 'Tiêu diệt vi khuẩn H.pylori đang tấn công niêm mạc.', 'Nâng pH dạ dày > 6 để tạo cục máu đông và ngăn Pepsin tiêu hủy nó.', 'Co mạch tại chỗ để giảm lưu lượng máu đến ổ loét.', 'Tăng cường lớp nhầy Bicarbonate để bao phủ ổ loét.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Chiến lược truyền máu hạn chế (Restrictive Strategy) khuyến cáo chỉ nên truyền hồng cầu lắng khi chỉ số Hemoglobin (Hb) xuống dưới:', '9 g/dL.', '8 g/dL.', '7 g/dL.', '10 g/dL.', 'C', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Đối với bệnh nhân xơ gan bị XHTH, tại sao việc dùng kháng sinh dự phòng là bắt buộc?', 'Để tiêu diệt vi khuẩn gây loét dạ dày H.pylori.', 'Phòng ngừa nhiễm trùng dịch cổ trướng và nhiễm khuẩn huyết.', 'Để làm giảm lượng NH3 do vi khuẩn ruột tạo ra.', 'Ngăn ngừa viêm phổi hít do nôn máu ồ ạt.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Biện pháp can thiệp nào sau đây được chỉ định khi nội soi thất bại và cần giảm áp lực tĩnh mạch cửa qua da?', 'Đặt ống thông Sengstaken-Blakemore.', 'Can thiệp mạch (TIPS).', 'X-quang can thiệp (Angiography).', 'Phẫu thuật khâu cầm máu ổ loét.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Trong nhận định toàn thân, dấu hiệu nào được coi là biểu hiện sớm và nhạy nhất của tình trạng mất máu cấp?', 'Huyết áp tâm thu tụt xuống dưới 90 mmHg.', 'Mạch nhanh, nhỏ, khó bắt.', 'Niêm mạc mắt nhợt và da xanh xao.', 'Bệnh nhân lờ đờ, chậm chạp hoặc hôn mê.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Cách kiểm tra huyết áp tư thế để phát hiện mất máu sớm là:', 'Kiểm tra HA ở hai tay khi bệnh nhân đang nằm.', 'HA tâm thu tụt > 20 mmHg khi chuyển từ nằm sang ngồi.', 'HA tâm trương tăng > 10 mmHg khi bệnh nhân đứng dậy.', 'HA tâm thu không đổi nhưng mạch tăng thêm 10 lần/phút.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Can thiệp ưu tiên số 1 của điều dưỡng khi nhận định bệnh nhân có sốc giảm thể tích do XHTH là:', 'Cho bệnh nhân uống nước muối sinh lý để bù dịch.', 'Lấy máu làm xét nghiệm công thức máu ngay lập tức.', 'Đặt bệnh nhân nằm đầu thấp, chân cao và thiết lập 2 đường truyền lớn.', 'Chuẩn bị dụng cụ để bác sĩ tiến hành nội soi cấp cứu.', 'C', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_9', 'NK-14', 'Chẩn đoán điều dưỡng "Nguy cơ hít sặc" đặc biệt quan trọng đối với đối tượng bệnh nhân nào?', 'Bệnh nhân có tiền sử dùng thuốc giảm đau NSAIDs kéo dài.', 'Bệnh nhân nôn máu ồ ạt kèm theo giảm tri giác.', 'Bệnh nhân bị phân đen đóng thành khuôn.', 'Bệnh nhân đang được điều trị bằng thuốc PPI liều cao.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Để theo dõi tình trạng giảm tưới máu mô thận, điều dưỡng cần duy trì lượng nước tiểu của bệnh nhân tối thiểu là:', '> 1.0 ml/kg/giờ.', '> 0.5 ml/kg/giờ.', '< 30 ml/giờ trong 24 giờ.', 'Khoảng 100 ml/24 giờ.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Trong kế hoạch chăm sóc bệnh nhân xơ gan có nguy cơ bệnh não gan, can thiệp nào giúp loại bỏ máu cũ (nguồn tạo NH3)?', 'Cho bệnh nhân uống thuốc co mạch tạng Terlipressin.', 'Thụt tháo đại tràng để loại bỏ máu cũ theo y lệnh.', 'Cho bệnh nhân ăn chế độ giàu protein để bù máu.', 'Hướng dẫn bệnh nhân tập thở sâu và ho có hiệu quả.', 'B', NULL, 'CLINICAL_APPLICATION'),
    ('BAI_9', 'NK-14', 'Bệnh nhân XHTH sau khi can thiệp nội soi cần tuyệt đối nhịn ăn trong bao lâu để phòng tái phát?', '6 giờ đầu sau nội soi.', '12 giờ đầu sau nội soi.', '24 giờ đầu sau nội soi.', 'Cho đến khi bệnh nhân cảm thấy đói.', 'C', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Dấu hiệu nào chứng tỏ kết quả mong đợi (NOC) của chẩn đoán "Nguy cơ chảy máu tái phát" đã đạt được?', 'Bệnh nhân vẫn còn đau rát vùng thượng vị.', 'Phân chuyển màu từ đen sang vàng.', 'Chỉ số SpO2 đạt 95% khi thở khí trời.', 'Niêm mạc miệng sạch, không có vết loét.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Khi thực hiện chẩn đoán "Suy giảm trao đổi khí", điều dưỡng cần hỗ trợ thở Oxy qua gọng mũi với lưu lượng bao nhiêu là phù hợp theo tài liệu?', '1 - 2 lít/phút.', '2 - 4 lít/phút.', '5 - 10 lít/phút.', 'Thở oxy qua mặt nạ có túi dự trữ.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Chế độ ăn cho bệnh nhân XHTH sau 24 giờ đã cầm máu ổn định nên là:', 'Ăn uống bình thường để lấy lại sức.', 'Ăn đồ ăn cứng, giàu chất xơ để kích thích tiêu hóa.', 'Ăn lỏng (sữa, cháo loãng), chia nhỏ 6-8 bữa/ngày.', 'Tiếp tục nhịn ăn hoàn toàn thêm 48 giờ nữa.', 'C', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Để phòng ngừa té ngã do hạ huyết áp tư thế, điều dưỡng hướng dẫn bệnh nhân nguyên tắc "3 bước" là:', 'Nằm → Ngồi tại giường → Đứng dậy từ từ khi có hỗ trợ.', 'Nằm → Đứng dậy ngay → Đi lại nhẹ nhàng.', 'Nằm đầu cao → Uống nước gừng → Đứng dậy.', 'Nằm đầu thấp → Co duỗi chân → Tự đi vệ sinh.', 'A', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Triệu chứng nào sau đây thuộc về biến chứng "Viêm phổi hít" ở bệnh nhân XHTH?', 'Đau thắt ngực, khó thở, thay đổi điện tâm đồ.', 'Suy hô hấp, tím tái, phổi có rale ẩm, rale nổ.', 'Rối loạn giấc ngủ, run vẫy (Asterixis).', 'Da xanh, móng tay khum hình thìa, mệt mỏi.', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Loại dung dịch tinh thể nào thường được ưu tiên sử dụng để bù dịch nhanh trong hồi sức XHTH?', 'Glucose 5% hoặc Glucose 10%.', 'Normal Saline 0.9% hoặc Lactated Ringer.', 'Dung dịch Albumin 5%.', 'Dung dịch cao phân tử (Dextran).', 'B', NULL, 'FOUNDATION'),
    ('BAI_9', 'NK-14', 'Một bệnh nhân vào viện với triệu chứng da xanh, niêm mạc nhợt, móng tay khum hình thìa nhưng không nôn máu. Đây là gợi ý của tình trạng:', 'Xuất huyết tiêu hóa cấp tính mức độ nặng.', 'Xuất huyết tiêu hóa mạn tính hoặc ẩn.', 'Sốc giảm thể tích giai đoạn mất bù.', 'Biến chứng nhồi máu cơ tim do thiếu máu.', 'B', NULL, 'CLINICAL_REASONING_ANALYSIS'),
    ('BAI_9', 'NK-14', 'Trong bảng phân loại mức độ mất máu, chỉ số hồng cầu (RBC) < 2 T/L tương ứng với mức độ nào?', 'Mức độ nhẹ.', 'Mức độ trung bình.', 'Mức độ nặng.', 'Chưa thể xác định nếu chưa có kết quả Hb.', 'C', NULL, 'FOUNDATION')
)
INSERT INTO questions (
  stem, category_id, professional_field_id, cognitive_level, cognitive_verified_at, cognitive_verified_by,
  option_a, option_b, option_c, option_d, correct_answer, explanation, language,
  source_document, source_document_id, question_type, parent_question_id, status,
  created_by, reviewed_by, created_at, updated_at
)
SELECT
  seed.stem, category.id, field.id, seed.cognitive_level, NULL, NULL,
  seed.option_a, seed.option_b, seed.option_c, seed.option_d, seed.correct_answer, seed.explanation, 'vi',
  'Câu hỏi ôn tập - Học phần chăm sóc bệnh cấp tính', NULL, 'ORIGINAL', NULL, 'APPROVED',
  'system-seed', 'system-seed', now(), now()
FROM seed_questions seed
JOIN question_categories category ON category.code = seed.category_code
JOIN professional_fields field ON field.code = seed.professional_field_code
WHERE NOT EXISTS (
  SELECT 1
  FROM questions existing
  WHERE existing.source_document = 'Câu hỏi ôn tập - Học phần chăm sóc bệnh cấp tính'
    AND existing.stem = seed.stem
);
